fn main() -> Void {
    let codes: Text[] = ["S", "M", "L", "XL", "XXL"];
    let perms: Text[][] = [];

    fn gen(perm: Text[], used: Bool[]) -> Void {
        if length(perm) == 5 {
            perms = perms + [perm];
            ret;
        }
        loop i in 0..5 {
            if !used[i] {
                let np: Text[] = perm + [codes[i]];
                let nu: Bool[] = used;
                nu[i] = true;
                gen(np, nu);
            }
        }
        ret;
    }

    gen([], [false, false, false, false, false]);

    let valid: Text[][] = [];
    loop p in perms {
        if p[0] == "S" || p[0] == "M" {
            valid = valid + [p];
        }
    }

    // lexicographic order by size code: S < M < L < XL < XXL
    // codes array is already in that order, and gen() iterates i in 0..5,
    // so perms are generated in lexicographic order already.

    let total: Int = length(valid);
    let seventh: Text[] = valid[6];

    fx {
        println("Total arrangements: ", total);
        print("7th arrangement: ");
        loop i in 0..5 {
            if i > 0 {
                print(" ");
            }
            print(seventh[i]);
        }
        println("");
        println("First code: ", seventh[0]);
        println("Last code: ", seventh[4]);
        println("Middle code: ", seventh[2]);
    }
    ret;
}

fn main() -> Void {
    let frames: Text[] = ["A", "B", "C", "D", "E"];
    let valid: Text[][] = [];
    let perms: Text[][] = [];

    // Generate all permutations of 5 frames
    fn gen(perm: Text[], used: Bool[]) -> Void {
        if length(perm) == 5 {
            perms = perms + [perm];
            ret;
        }
        loop i in 0..5 {
            if !used[i] {
                let newPerm: Text[] = perm + [frames[i]];
                let newUsed: Bool[] = used;
                newUsed[i] = true;
                gen(newPerm, newUsed);
            }
        }
        ret;
    }

    let emptyPerm: Text[] = [];
    let usedInit: Bool[] = [false, false, false, false, false];
    gen(emptyPerm, usedInit);

    // Sort perms lexicographically
    fn lessThan(a: Text[], b: Text[]) -> Bool {
        loop i in 0..5 {
            if a[i] != b[i] {
                ret a[i] < b[i];
            }
        }
        ret false;
    }

    // Bubble sort
    loop i in 0..length(perms) {
        loop j in 0..(length(perms) - 1 - i) {
            if lessThan(perms[j + 1], perms[j]) {
                let tmp: Text[] = perms[j];
                perms[j] = perms[j + 1];
                perms[j + 1] = tmp;
            }
        }
    }

    // Filter valid
    loop p in perms {
        let posA: Int = -1;
        let posB: Int = -1;
        let posC: Int = -1;
        let posD: Int = -1;
        let posE: Int = -1;
        loop k in 0..5 {
            if p[k] == "A" { posA = k; }
            if p[k] == "B" { posB = k; }
            if p[k] == "C" { posC = k; }
            if p[k] == "D" { posD = k; }
            if p[k] == "E" { posE = k; }
        }
        if posA < posB && posC < posD && posE != 0 {
            valid = valid + [p];
        }
    }

    let sixth: Text[] = valid[5];
    let posE6: Int = -1;
    let posA6: Int = -1;
    loop k in 0..5 {
        if sixth[k] == "E" { posE6 = k; }
        if sixth[k] == "A" { posA6 = k; }
    }

    fx {
        println("Valid placements: ", length(valid));
        println("6th placement: ", sixth[0], " ", sixth[1], " ", sixth[2], " ", sixth[3], " ", sixth[4]);
        println("Position of E: ", posE6 + 1);
        println("Position of A: ", posA6 + 1);
        println("Frame at position 3: ", sixth[2]);
    }
    ret;
}

fn main() -> Void {
    let count: Int = 0;
    let second: Int[] = [];
    let last: Int[] = [];

    loop d1 in 1..4 {
        loop d2 in 0..4 {
            loop d3 in 0..4 {
                loop d4 in 0..3 {
                    if d1 + d2 + d3 + d4 == 5 {
                        count = count + 1;
                        if count == 2 {
                            second = [d1, d2, d3, d4];
                        }
                        last = [d1, d2, d3, d4];
                    }
                }
            }
        }
    }

    let day2: Int = second[1];
    let zeros: Int = 0;
    loop v in second {
        if v == 0 {
            zeros = zeros + 1;
        }
    }

    fx {
        println("Valid sequences: ", count);
        println("2nd sequence: ", second[0], " ", second[1], " ", second[2], " ", second[3]);
        println("Last sequence: ", last[0], " ", last[1], " ", last[2], " ", last[3]);
        println("Day 2 reading: ", day2);
        println("Zero-reading days: ", zeros);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [4, 3, 5, 2, 4],
        [3, 6, 4, 3, 5],
        [5, 4, 7, 4, 6]
    ];
    let rows: Int = length(grid);
    let cols: Int = length(grid[0]);
    let cold: Int = 0;
    let warm: Int = 0;
    let maxTemp: Int = -1000000;
    let maxR: Int = 0;
    let maxC: Int = 0;
    let rowAvgs: Real[] = [];
    loop r in 0..rows {
        let rowSum: Int = 0;
        loop c in 0..cols {
            let t: Int = grid[r][c];
            rowSum = rowSum + t;
            if t <= 4 {
                cold = cold + 1;
            }
            if t >= 5 {
                warm = warm + 1;
            }
            if t > maxTemp {
                maxTemp = t;
                maxR = r;
                maxC = c;
            }
        }
        let avg: Real = rowSum * 1.0 / cols;
        rowAvgs = rowAvgs + [avg];
    }
    let allColdRows: Int[] = [];
    loop r in 0..rows {
        let allCold: Bool = true;
        loop c in 0..cols {
            if grid[r][c] > 4 {
                allCold = false;
            }
        }
        if allCold {
            allColdRows = allColdRows + [r + 1];
        }
    }
    let allWarmCols: Int[] = [];
    loop c in 0..cols {
        let allWarm: Bool = true;
        loop r in 0..rows {
            if grid[r][c] < 5 {
                allWarm = false;
            }
        }
        if allWarm {
            allWarmCols = allWarmCols + [c + 1];
        }
    }
    let coldRowsText: Text = "None";
    if length(allColdRows) > 0 {
        coldRowsText = int_to_text(allColdRows[0]);
        loop i in 1..length(allColdRows) {
            coldRowsText = coldRowsText + ", " + int_to_text(allColdRows[i]);
        }
    }
    let warmColsText: Text = "None";
    if length(allWarmCols) > 0 {
        warmColsText = int_to_text(allWarmCols[0]);
        loop i in 1..length(allWarmCols) {
            warmColsText = warmColsText + ", " + int_to_text(allWarmCols[i]);
