}

fn main() -> Void {
    let grid: Int[][] = [
        [2, 5, 3],
        [4, 6, 1],
        [3, 2, 5]
    ];

    let bright: Int = 0;
    let dim: Int = 0;
    let total: Int = 0;

    loop r in 0..3 {
        loop c in 0..3 {
            let v: Int = grid[r][c];
            total = total + v;
            if v >= 4 {
                bright = bright + 1;
            }
            if v <= 2 {
                dim = dim + 1;
            }
        }
    }

    let balanced: Int[] = [];
    let ranges: Int[] = [];

    loop r in 0..3 {
        let row: Int[] = grid[r];
        let mn: Int = min_of(row);
        let mx: Int = max_of(row);
        let diff: Int = mx - mn;
        ranges = ranges + [diff];
        if diff <= 3 {
            balanced = balanced + [r + 1];
        }
    }

    let key: Int = grid[1][1];

    let balText: Text = "";
    if length(balanced) == 0 {
        balText = "None";
    } else {
        loop i in 0..length(balanced) {
            if i > 0 {
                balText = balText + ",";
            }
            balText = balText + int_to_text(balanced[i]);
        }
    }

    let rangeText: Text = int_to_text(ranges[0]) + " " + int_to_text(ranges[1]) + " " + int_to_text(ranges[2]);

    fx {
        println("Bright cells: ", bright);
        println("Dim cells: ", dim);
        println("Balanced rows: ", balText);
        println("Key light exposure: ", key);
        println("Row ranges: ", rangeText);
        println("Grid sum: ", total);
    }
    ret;
}

fn main() -> Void {
    let temps: Int[][] = [
        [350, 375],
        [400, 325],
        [375, 400],
        [325, 350]
    ];

    let hotCount: Int = 0;
    let coolCount: Int = 0;
    let mixedRows: Int[] = [];
    let evenCols: Int[] = [];
    let total: Int = 0;

    loop r in 0..4 {
        let hotInRow: Int = 0;
        loop c in 0..2 {
            let t: Int = temps[r][c];
            total = total + t;
            if t >= 375 {
                hotCount = hotCount + 1;
                hotInRow = hotInRow + 1;
            }
            if t <= 350 {
                coolCount = coolCount + 1;
            }
        }
        if hotInRow == 1 {
            mixedRows = mixedRows + [r + 1];
        }
    }

    loop c in 0..2 {
        let first: Int = temps[0][c];
        let same: Bool = true;
        loop r in 1..4 {
            if temps[r][c] != first {
                same = false;
            }
        }
        if same {
            evenCols = evenCols + [c + 1];
        }
    }

    let avg: Real = total * 1.0 / 8;

    let bestRow: Int = 0;
    let bestSum: Int = temps[0][0] + temps[0][1];
    loop r in 1..4 {
        let rowSum: Int = temps[r][0] + temps[r][1];
        if rowSum > bestSum {
            bestSum = rowSum;
            bestRow = r;
        }
    }

    let mixedText: Text = "None";
    if length(mixedRows) > 0 {
        mixedText = int_to_text(mixedRows[0]);
        loop i in 1..length(mixedRows) {
            mixedText = mixedText + "," + int_to_text(mixedRows[i]);
        }
    }

    let evenText: Text = "None";
    if length(evenCols) > 0 {
        evenText = int_to_text(evenCols[0]);
        loop i in 1..length(evenCols) {
            evenText = evenText + "," + int_to_text(evenCols[i]);
        }
    }

    let avgText: Text = format_float(avg, 2);
    let dotPos: Int = index_of(avgText, ".");
    if dotPos >= 0 {
        let afterDot: Text = avgText[dotPos + 1..];
        if ends_with(afterDot, "0") {
            avgText = avgText[..string_len(avgText) - 1];
        }
    }

    fx {
        println("Hot racks: ", hotCount);
        println("Cool racks: ", coolCount);
        println("Mixed rows: ", mixedText);
        println("Even columns: ", evenText);
        println("Average temperature: ", avgText);
        println("Hottest row: ", bestRow + 1);
    }
    ret;
}

