fn main() -> Void {
    let times: Int[] = [47, 63, 55, 40, 71, 58];
    let fuel: Int[] = [60, 60, 60, 60, 60, 60];
    let refills: Int = 0;

    loop i in 0..length(times) {
        fuel[i] = fuel[i] - times[i];
        if fuel[i] <= 0 {
            fuel[i] = 60;
            refills = refills + 1;
        }
    }

    let totalRemaining: Int = 0;
    loop i in 0..length(fuel) {
        totalRemaining = totalRemaining + fuel[i];
    }
    let totalConsumed: Int = 6 * 60 - totalRemaining;

    let minFuel: Int = fuel[0];
    let minIdx: Int = 0;
    loop i in 1..length(fuel) {
        if fuel[i] < minFuel {
            minFuel = fuel[i];
            minIdx = i;
        }
    }

    fx {
        println("Refills needed: ", refills);
        println("Total fuel minutes consumed: ", totalConsumed);
        println("Lantern with least remaining fuel: ", minIdx + 1);
    }
