    let root: ToonNode = toon_root(doc);
    let stations: ToonNode = toon_key(root, "stations");
    let robotX: Int = toon_get_int(root, "robotX");
    let robotY: Int = toon_get_int(root, "robotY");
    let minLevel: Int = toon_get_int(root, "minLevel");

    let bestLevel: Int = -1;
    let bestX: Int = 0;
    let bestY: Int = 0;
    let totalLevel: Int = 0;
    let nearby: Int = 0;

    loop i in 0..toon_len(stations) {
        let st: ToonNode = toon_at(stations, i);
        let x: Int = toon_get_int(st, "x");
        let y: Int = toon_get_int(st, "y");
        let level: Int = toon_get_int(st, "level");
        let active: Bool = toon_get_bool(st, "active");
        let dist: Int = abs(x - robotX) + abs(y - robotY);

        if active {
            totalLevel = totalLevel + level;
            if level > bestLevel {
                bestLevel = level;
                bestX = x;
                bestY = y;
            }
            if dist <= 2 {
                nearby = nearby + 1;
            }
            if level >= minLevel {
                fx {
                    println(int_to_text(x), ",", int_to_text(y), ": ready at distance ", dist);
                }
            }
        }
    }

    fx {
        println("Best charge: ", int_to_text(bestX), ",", int_to_text(bestY));
    }

    loop i in 0..toon_len(stations) {
        let st: ToonNode = toon_at(stations, i);
        let x: Int = toon_get_int(st, "x");
        let y: Int = toon_get_int(st, "y");
        let active: Bool = toon_get_bool(st, "active");
        if !active {
            fx {
                println(int_to_text(x), ",", int_to_text(y), ": offline");
            }
        }
    }

    fx {
        println("Total level: ", totalLevel);
        println("Nearby: ", nearby);
    }

    toon_close(doc);
    ret;
}

