fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("tanks.json"); }
    let root: ToonNode = toon_root(doc);

    let n: Int = toon_len(root);
    let checkCount: Int = 0;
    let totalTemp: Int = 0;
    let okSpecies: Text = "none";
    let foundOk: Bool = false;

    let checkFlags: Bool[] = [];
    let tankIds: Text[] = [];
    let phs: Real[] = [];
    let temps: Int[] = [];

    loop i in 0..n {
        let row: ToonNode = toon_at(root, i);
        let tank: Text = toon_get_text_or(row, "tank", "");
        let ph: Real = toon_get_real_or(row, "ph", 0.0);
        let temp: Int = toon_get_int_or(row, "temp_c", 0);
        let days: Int = toon_get_int_or(row, "last_change_days", 0);
        let species: Text = toon_get_text_or(row, "species", "");

        totalTemp = totalTemp + temp;

        let needsCheck: Bool = ph < 6.5 || ph > 8.4 || temp < 22 || temp > 27 || days > 14;
        checkFlags = checkFlags + [needsCheck];
        tankIds = tankIds + [tank];
        phs = phs + [ph];
        temps = temps + [temp];

        if needsCheck {
            checkCount = checkCount + 1;
        } else if !foundOk {
            okSpecies = species;
            foundOk = true;
        }
    }

    let indices: Int[] = [];
    loop i in 0..n {
        if checkFlags[i] {
            indices = indices + [i];
        }
    }

    let sortedIdx: Int[] = sorted(indices);
    let sortedTanks: Text[] = [];
    loop i in 0..length(sortedIdx) {
        sortedTanks = sortedTanks + [tankIds[sortedIdx[i]]];
    }
    let finalIdx: Int[] = [];
    loop i in 0..length(sortedIdx) {
        let target: Text = sortedTanks[i];
        loop j in 0..length(indices) {
            if tankIds[indices[j]] == target {
                finalIdx = finalIdx + [indices[j]];
                break;
            }
        }
    }

    fx {
        println("CHECK ", checkCount);
        loop i in 0..length(finalIdx) {
            let idx: Int = finalIdx[i];
            println(tankIds[idx], " ", format_float(phs[idx], 1), " ", temps[idx]);
        }
        let avg: Real = 0.0;
        if n > 0 {
            avg = totalTemp * 1.0 / n;
        }
        println("AVG_TEMP ", format_float(avg, 1));
        println("OK_SPECIES ", okSpecies);
    }

    toon_close(doc);
    ret;
}

type Animal {
    id: Int = 0;
    species: Text = "";
    age_months: Int = 0;
    days_waiting: Int = 0;
    vaccinated: Bool = false;
    name: Text = "";
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("shelter.json"); }
    let root: ToonNode = toon_root(doc);
    let count: Int = toon_len(root);

    let animals: Animal[] = [];
    loop i in 0..count {
        let row: ToonNode = toon_at(root, i);
        let a: Animal = new Animal {
            id: toon_get_int_or(row, "id", 0),
            species: toon_get_text_or(row, "species", ""),
            age_months: toon_get_int_or(row, "age_months", 0),
            days_waiting: toon_get_int_or(row, "days_waiting", 0),
            vaccinated: toon_get_bool_or(row, "vaccinated", false),
            name: toon_get_text_or(row, "name", "")
        };
        animals = animals + [a];
    }

    let speciesMap: Map[Text, Int] = {};
    loop a in animals {
        speciesMap[a.species] = get(speciesMap, a.species, 0) + 1;
    }
    let speciesList: Text[] = keys(speciesMap);
    let sortedSpecies: Text[] = sorted(speciesList);

    fx {
        loop s in sortedSpecies {
            println("SPECIES ", s, " ", speciesMap[s]);
        }
    }

    let eligible: Int = 0;
    loop a in animals {
        if a.vaccinated && a.days_waiting > 30 {
            eligible = eligible + 1;
        }
    }
    fx {
        println("ELIGIBLE ", eligible);
    }

    let oldestIdx: Int = 0;
    loop i in 1..count {
        if animals[i].age_months > animals[oldestIdx].age_months {
            oldestIdx = i;
        }
        if animals[i].age_months == animals[oldestIdx].age_months && animals[i].id < animals[oldestIdx].id {
            oldestIdx = i;
        }
    }
    fx {
        println("OLDEST ", animals[oldestIdx].name, " ", animals[oldestIdx].id);
    }

    let sortedAnimals: Animal[] = sorted_by_desc(animals, "days_waiting");
    let topCount: Int = 3;
    if count < topCount {
        topCount = count;
    }
    fx {
        loop i in 0..topCount {
            println("WAIT ", sortedAnimals[i].id, " ", sortedAnimals[i].name, " ", sortedAnimals[i].days_waiting);
        }
    }

    toon_close(doc);
    ret;
}

