fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("matches.json"); }
    let root: ToonNode = toon_root(doc);

    let wins: Map[Text, Int] = {};
    let losses: Map[Text, Int] = {};

    fx {
        println("Tournament Match Ranking");
        println("========================");
    }

    loop i in 0..toon_len(root) {
        let row: ToonNode = toon_at(root, i);
        let id: Int = toon_get_int_or(row, "id", 0);
        let winner: Text = toon_get_text_or(row, "winner", "?");
        let loser: Text = toon_get_text_or(row, "loser", "?");
        let turns: Int = toon_get_int_or(row, "turns", 0);
        let tiebreak: Bool = toon_get_bool_or(row, "tiebreak", false);

        wins[winner] = get(wins, winner, 0) + 1;
        losses[loser] = get(losses, loser, 0) + 1;

        let tb: Text = if tiebreak { " *" } else { "" };
        fx {
            println("MATCH ", id, ": ", winner, " def. ", loser, " in ", turns, " turns", tb);
        }
    }

    let bestName: Text = "";
    let bestWins: Int = -1;
    loop name in wins {
        let w: Int = wins[name];
        if w > bestWins || (w == bestWins && name < bestName) {
            bestWins = w;
            bestName = name;
        }
    }

    let fewName: Text = "";
    let fewLosses: Int = -1;
    loop name in losses {
        let l: Int = losses[name];
        if fewLosses == -1 || l < fewLosses || (l == fewLosses && name < fewName) {
            fewLosses = l;
            fewName = name;
        }
    }

    fx {
        println("MOST WINS: ", bestName, " (", bestWins, ")");
        println("FEWEST LOSSES: ", fewName, " (", fewLosses, ")");
    }

    toon_close(doc);
    ret;
}

