fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("entries.json"); }
    let root: ToonNode = toon_root(doc);

    let n: Int = toon_len(root);
    let days: Int[] = [];
    let steps: Int[] = [];
    let actives: Bool[] = [];
    let moods: Text[] = [];

    loop i in 0..n {
        let row: ToonNode = toon_at(root, i);
        let d: Int = toon_get_int_or(row, "day", 0);
        let s: Int = toon_get_int_or(row, "steps", 0);
        let a: Bool = toon_get_bool_or(row, "active", false);
        let m: Text = toon_get_text_or(row, "mood", "-");
        days = days + [d];
        steps = steps + [s];
        actives = actives + [a];
        moods = moods + [m];
    }

    let totalSteps: Int = 0;
    let activeDays: Int = 0;
    let bestDay: Int = 0;
    let bestSteps: Int = -1;
    let curStreak: Int = 0;
    let bestStreak: Int = 0;

    loop i in 0..n {
        totalSteps = totalSteps + steps[i];
        if actives[i] {
            activeDays = activeDays + 1;
            if i > 0 && actives[i - 1] && days[i] == days[i - 1] + 1 {
                curStreak = curStreak + 1;
            } else {
                curStreak = 1;
            }
            if curStreak > bestStreak {
                bestStreak = curStreak;
            }
        } else {
            curStreak = 0;
        }
        if steps[i] > bestSteps || (steps[i] == bestSteps && days[i] < bestDay) {
            bestSteps = steps[i];
            bestDay = days[i];
        }
    }

    fx {
        println("Fitness Streak Report");
        println("---------------------");
        loop i in 0..n {
            let dText: Text = int_to_text(days[i]);
            let sText: Text = int_to_text(steps[i]);
            let aText: Text = if actives[i] { "Y" } else { "N" };
            let mText: Text = moods[i];
            let dPad: Int = 3 - string_len(dText);
            let sPad: Int = 6 - string_len(sText);
            let dPadded: Text = repeat(" ", dPad) + dText;
            let sPadded: Text = repeat(" ", sPad) + sText;
            println(dPadded, " ", sPadded, " ", aText, " ", mText);
        }
        println("TOTAL STEPS: ", totalSteps);
        println("ACTIVE DAYS: ", activeDays);
        println("LONGEST STREAK: ", bestStreak, " days");
        println("BEST DAY: ", bestDay, " (", bestSteps, " steps)");
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    let lines: Text[] = [];
    fx {
        lines = read_lines("watering_log.txt");
    }

    let maxLines: Int = 30;
    let count: Int = length(lines);
    if count > maxLines {
        count = maxLines;
    }

    let events: Int = 0;
    let plots: Map[Text, Bool] = {};
    let inRange: Int = 0;
    let outOfRange: Int = 0;
    let totalLitres: Int = 0;
    let mondayLitres: Int = 0;
    let weekendEvents: Int = 0;
    let cropTotals: Map[Text, Int] = {};
    let plotNoCounts: Map[Text, Int] = {};

    loop i in 0..count {
        let line: Text = lines[i];
        if line == "" {
            continue;
        }
        let parts: Text[] = split(line, " ");
        let plotId: Int = parse_int(parts[0]);
        let crop: Text = parts[1];
        let litres: Int = parse_int(parts[2]);
        let day: Text = parts[3];
        let okFlag: Text = parts[4];

        events = events + 1;

        let pidKey: Text = int_to_text(plotId);
        plots[pidKey] = true;

        if okFlag == "YES" {
            inRange = inRange + 1;
        } else {
            outOfRange = outOfRange + 1;
            plotNoCounts[pidKey] = get(plotNoCounts, pidKey, 0) + 1;
        }

        totalLitres = totalLitres + litres;

        if day == "Mon" {
            mondayLitres = mondayLitres + litres;
        }
        if day == "Sat" or day == "Sun" {
            weekendEvents = weekendEvents + 1;
        }

        cropTotals[crop] = get(cropTotals, crop, 0) + litres;
    }

    let avgLitres: Real = 0.0;
    if events > 0 {
        avgLitres = totalLitres * 1.0 / events;
    }

    let topCrop: Text = "";
    let topCropLitres: Int = -1;
    loop c in cropTotals {
        let cLitres: Int = cropTotals[c];
        if cLitres > topCropLitres or (cLitres == topCropLitres and c < topCrop) {
            topCrop = c;
            topCropLitres = cLitres;
        }
    }

    let worstPlot: Int = -1;
    let worstCount: Int = 0;
    loop p in plotNoCounts {
        let pCount: Int = plotNoCounts[p];
        let pId: Int = parse_int(p);
        if pCount > worstCount or (pCount == worstCount and pId < worstPlot) {
            worstPlot = pId;
            worstCount = pCount;
        }
    }

    let worstPlotText: Text = "NONE";
    if worstPlot != -1 {
        worstPlotText = int_to_text(worstPlot);
    }

    fx {
        println("Events: ", events);
        println("Plots: ", length(plots));
        println("In range: ", inRange);
        println("Out of range: ", outOfRange);
        println("Total litres: ", totalLitres);
        println("Avg litres: ", format_float(avgLitres, 2));
        println("Monday litres: ", mondayLitres);
        println("Weekend events (Sat+Sun): ", weekendEvents);
        println("Top crop: ", topCrop);
        println("Top crop litres: ", topCropLitres);
        println("Worst plot (most out-of-range): ", worstPlotText);
    }
    ret;
}

