            let rec: ToonNode = toon_key(root, name);
            if toon_is_obj(rec) && toon_has_key(rec, "orders") && toon_has_key(rec, "balance_due") && toon_is_int(toon_key(rec, "orders")) && toon_is_int(toon_key(rec, "balance_due")) {
