fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "[{\"bib\":1001,\"name\":\"Aria\",\"split_km\":5,\"split_sec\":1320},{\"bib\":1002,\"name\":\"Ben\",\"split_km\":5,\"split_sec\":1410},{\"bib\":1003,\"name\":\"Cleo\",\"split_km\":10,\"split_sec\":2760},{\"bib\":1004,\"name\":\"Dev\",\"split_km\":10,\"split_sec\":2905}]";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);

    let bestBib: Int = 0;
    let bestPace: Real = 0.0;
    let hasBest: Bool = false;

    loop i in 0..toon_len(root) {
        let row: ToonNode = toon_at(root, i);
        let bib: Int = toon_get_int_or(row, "bib", 0);
        let name: Text = toon_get_text_or(row, "name", "");
        let km: Int = toon_get_int_or(row, "split_km", 0);
        let sec: Int = toon_get_int_or(row, "split_sec", 0);

        if !toon_is_int(toon_key_or(row, "split_km", toon_null())) || !toon_is_int(toon_key_or(row, "split_sec", toon_null())) || km == 0 {
            fx {
                println("BIB ", bib, " : ", name, " : INVALID");
            }
        } else {
            let pace: Real = sec * 1.0 / km;
            fx {
                println("BIB ", bib, " : ", name, " : ", km, "km : ", format_float(pace, 2));
            }
            if !hasBest || pace < bestPace || (pace == bestPace && bib < bestBib) {
                bestBib = bib;
                bestPace = pace;
                hasBest = true;
            }
        }
    }

    fx {
        println("FASTEST : bib=", bestBib, " pace=", format_float(bestPace, 2));
    }

    toon_close(doc);
    ret;
}

