type Candidate {
    name: Text = "";
    count: Int = 0;
}

fn main() -> Void {
    let votes: Text[] = ["Alice", "Bob", "Alice", "Charlie", "Bob", "Alice", "Dave", "Charlie", "Bob", "Alice", "Dave", "Alice", "Bob", "Charlie", "Alice", "Dave", "Bob", "Alice", "Charlie", "Dave"];
    let counts: Map[Text, Int] = {};
    loop v in votes {
        counts[v] = get(counts, v, 0) + 1;
    }
    let names: Text[] = keys(counts);
    let sortedNames: Text[] = sorted(names);
    let candidates: Candidate[] = [];
    loop n in sortedNames {
        let c: Candidate = new Candidate { name: n, count: counts[n] };
        candidates = candidates + [c];
    }
    let sortedCandidates: Candidate[] = sorted_by_desc(candidates, "count");
    fx {
        loop c in sortedCandidates {
            println(c.name, ": ", c.count);
        }
    }
    ret;
