    let caps: Text[] = ["Red", "Blue", "Green", "Red", "Blue", "Red", "Green", "Blue", "Red", "Green", "Blue", "Red", "Green", "Blue", "Red"];
    let counts: Map[Text, Int] = {};
    loop c in caps {
        counts[c] = get(counts, c, 0) + 1;
    }
    let colors: Text[] = keys(counts);
    let sorted: Text[] = sorted(colors);
    let n: Int = length(sorted);
    let out: Text[] = [];
    loop i in 0..n {
        out = out + [sorted[i]];
    }
    loop i in 0..n {
        let maxIdx: Int = i;
        loop j in i + 1..n {
            let cj: Int = counts[out[j]];
            let cm: Int = counts[out[maxIdx]];
            if cj > cm {
                maxIdx = j;
            } else if cj == cm && out[j] < out[maxIdx] {
                maxIdx = j;
            }
        }
        if maxIdx != i {
            let tmp: Text = out[i];
            out[i] = out[maxIdx];
            out[maxIdx] = tmp;
        }
    }
    fx {
        loop c in out {
            println(c, ": ", counts[c]);
        }
    }
    ret;
}

