fn countWays(n: Int) -> Int {
    if n == 0 {
        ret 1;
    }
    if n < 0 {
        ret 0;
    }
    let total: Int = 0;
    if n >= 1 {
        total = total + countWays(n - 1);
    }
    if n >= 3 {
        total = total + countWays(n - 3);
    }
    if n >= 4 {
        total = total + countWays(n - 4);
    }
    ret total;
}

