fn main() -> Void {
    let grid: Text[] = ["F..F..", "FF.F..", "..FF.F", "F..FF.", ".FF..F", "F..F.F"];
    let rows: Int = 6;
    let cols: Int = 6;
    let visited: Bool[][] = [];
    loop r in 0..rows {
        let row: Bool[] = [];
        loop c in 0..cols {
            row = row + [false];
        }
        visited = visited + [row];
    }

    let totalFish: Int = 0;
    loop r in 0..rows {
        loop c in 0..cols {
            if grid[r][c] == "F" {
                totalFish = totalFish + 1;
            }
        }
    }

    let largest: Int = 0;
    loop r in 0..rows {
        loop c in 0..cols {
            if grid[r][c] == "F" && !visited[r][c] {
                let size: Int = 0;
                let stack: Int[] = [];
                stack = stack + [r * cols + c];
                visited[r][c] = true;
                loop stack.length > 0 {
                    let pos: Int = stack[stack.length - 1];
                    stack = stack[..stack.length - 1];
                    let cr: Int = pos div cols;
                    let cc: Int = pos % cols;
                    size = size + 1;
                    let dr: Int[] = [-1, 1, 0, 0];
                    let dc: Int[] = [0, 0, -1, 1];
                    loop k in 0..4 {
                        let nr: Int = cr + dr[k];
                        let nc: Int = cc + dc[k];
                        if nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == "F" && !visited[nr][nc] {
                            visited[nr][nc] = true;
                            stack = stack + [nr * cols + nc];
                        }
                    }
                }
                if size > largest {
                    largest = size;
                }
            }
        }
    }

    fx {
        println("LARGEST=", largest);
        println("TOTAL_FISH=", totalFish);
    }
    ret;
}

