fn main() -> Void {
    let grid: Int[][] = [
        [5, 0, 3, 2],
        [1, 4, 0, 6],
        [2, 0, 7, 1],
        [3, 5, 2, 4]
    ];
    let rows: Int = length(grid);
    let cols: Int = length(grid[0]);

    let score: Int[][] = [];
    let steps: Int[][] = [];

    loop r in 0..rows {
        let srow: Int[] = [];
        let krow: Int[] = [];
        loop c in 0..cols {
            srow = srow + [0];
            krow = krow + [0];
        }
        score = score + [srow];
        steps = steps + [krow];
    }

    loop r in 0..rows {
        loop c in 0..cols {
            if r == 0 && c == 0 {
                score[0][0] = grid[0][0];
                steps[0][0] = 1;
            } else if r == 0 {
                score[r][c] = score[r][c - 1] + grid[r][c];
                steps[r][c] = steps[r][c - 1] + 1;
            } else if c == 0 {
                score[r][c] = score[r - 1][c] + grid[r][c];
                steps[r][c] = steps[r - 1][c] + 1;
            } else {
                let fromTop: Int = score[r - 1][c];
                let fromLeft: Int = score[r][c - 1];
                if fromTop > fromLeft {
                    score[r][c] = fromTop + grid[r][c];
                    steps[r][c] = steps[r - 1][c] + 1;
                } else if fromLeft > fromTop {
                    score[r][c] = fromLeft + grid[r][c];
                    steps[r][c] = steps[r][c - 1] + 1;
                } else {
                    score[r][c] = fromTop + grid[r][c];
                    if steps[r - 1][c] < steps[r][c - 1] {
                        steps[r][c] = steps[r - 1][c] + 1;
                    } else {
                        steps[r][c] = steps[r][c - 1] + 1;
                    }
                }
            }
        }
    }

    let maxScore: Int = score[rows - 1][cols - 1];
    let minSteps: Int = steps[rows - 1][cols - 1];

    fx {
        println("MAX_SCORE=", maxScore);
        println("CHECKPOINTS_VISITED=", minSteps);
    }
    ret;
}

