fn main() -> Void {
    let x: Int = 0;
    let y: Int = 0;
    let dir: Int = 0; // 0=E, 1=N, 2=W, 3=S

    // F:3
    let d1: Int = 3;
    if dir == 0 { x = x + d1; }
    if dir == 1 { y = y + d1; }
    if dir == 2 { x = x - d1; }
    if dir == 3 { y = y - d1; }

    // L
    dir = (dir + 1) % 4;

    // F:2
    let d2: Int = 2;
    if dir == 0 { x = x + d2; }
    if dir == 1 { y = y + d2; }
    if dir == 2 { x = x - d2; }
    if dir == 3 { y = y - d2; }

    // L
    dir = (dir + 1) % 4;

    // F:4
    let d3: Int = 4;
    if dir == 0 { x = x + d3; }
    if dir == 1 { y = y + d3; }
    if dir == 2 { x = x - d3; }
    if dir == 3 { y = y - d3; }

    // R
    dir = (dir + 3) % 4;

    // F:1
    let d4: Int = 1;
    if dir == 0 { x = x + d4; }
    if dir == 1 { y = y + d4; }
    if dir == 2 { x = x - d4; }
    if dir == 3 { y = y - d4; }

    // R
    dir = (dir + 3) % 4;

    // F:5
    let d5: Int = 5;
    if dir == 0 { x = x + d5; }
    if dir == 1 { y = y + d5; }
    if dir == 2 { x = x - d5; }
    if dir == 3 { y = y - d5; }

    let dist: Real = sqrt(Real(x * x + y * y));
    let distRounded: Real = round_to(dist, 2);

    fx {
        println("Final position: (", x, ",", y, ")");
        println("Distance from origin: ", format_float(distRounded, 2));
    }
    ret;
}

