        loop j in i + 1..n {
            let diff: Int = j - i;
            let dist: Int = min(diff, n - diff);
            if dist == 2 {
                let pair: Text = cells[i] + cells[j];
                pairs = pairs + [pair];
            }
        }
    }

    let joined: Text = join(pairs, ", ");
    fx {
        println("Pairs: ", joined);
        println("Count: ", length(pairs));
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [1, 2, 3],
        [4, 5, 6],
        [7, 8, 9]
    ];
    let r: Int = 0;
    let c: Int = 0;

    // Move 1: Right
    let tmp: Int = grid[r][c];
    grid[r][c] = grid[r][c + 1];
    grid[r][c + 1] = tmp;
    c = c + 1;

    fx {
        println(grid[0][0], " ", grid[0][1], " ", grid[0][2]);
        println(grid[1][0], " ", grid[1][1], " ", grid[1][2]);
        println(grid[2][0], " ", grid[2][1], " ", grid[2][2]);
    }

    // Move 2: Down
    tmp = grid[r][c];
    grid[r][c] = grid[r + 1][c];
    grid[r + 1][c] = tmp;
    r = r + 1;

    fx {
        println(grid[0][0], " ", grid[0][1], " ", grid[0][2]);
        println(grid[1][0], " ", grid[1][1], " ", grid[1][2]);
        println(grid[2][0], " ", grid[2][1], " ", grid[2][2]);
    }

    // Move 3: Left
    tmp = grid[r][c];
    grid[r][c] = grid[r][c - 1];
    grid[r][c - 1] = tmp;
    c = c - 1;

    fx {
        println(grid[0][0], " ", grid[0][1], " ", grid[0][2]);
        println(grid[1][0], " ", grid[1][1], " ", grid[1][2]);
        println(grid[2][0], " ", grid[2][1], " ", grid[2][2]);
    }

    // Move 4: Up
    tmp = grid[r][c];
    grid[r][c] = grid[r - 1][c];
    grid[r - 1][c] = tmp;
    r = r - 1;

    fx {
        println(grid[0][0], " ", grid[0][1], " ", grid[0][2]);
        println(grid[1][0], " ", grid[1][1], " ", grid[1][2]);
        println(grid[2][0], " ", grid[2][1], " ", grid[2][2]);
        println("Moves: 4");
    }

    ret;
}

fn isPalindrome(s: Text) -> Bool {
    let n: Int = string_len(s);
    loop i in 0..(n div 2) {
        if s[i] != s[n - 1 - i] {
            ret false;
        }
    }
    ret true;
}

fn countOnes(s: Text) -> Int {
    let c: Int = 0;
    loop ch in s {
        if ch == "1" {
            c = c + 1;
        }
    }
    ret c;
}

fn toBinary4(n: Int) -> Text {
    let s: Text = "";
    loop i in 0..4 {
        let bit: Int = (n >> (3 - i)) & 1;
        s = s + int_to_text(bit);
    }
    ret s;
}

fn main() -> Void {
    let count: Int = 0;
    loop n in 0..16 {
        let s: Text = toBinary4(n);
        let ones: Int = countOnes(s);
        let balanced: Bool = ones == 2;
        let pal: Bool = isPalindrome(s);
        if balanced || pal {
            count = count + 1;
            fx {
                println(s);
            }
        }
    }
    fx {
        println("Accepted: ", count);
    }
    ret;
}

