fn main() -> Void {
    let presses: Text[] = ["FEED", "BURST", "STOP", "BURST", "FEED", "FEED", "STOP", "BURST", "FEED", "STOP", "STOP", "BURST"];
    let state: Text = "IDLE";
    let dispensingTicks: Int = 0;
    let redundantStops: Int = 0;
    let redundantFeeds: Int = 0;

    loop p in presses {
        if p == "FEED" {
            if state == "DISPENSING" {
                redundantFeeds = redundantFeeds + 1;
            } else {
                state = "DISPENSING";
            }
        } else if p == "STOP" {
            if state == "IDLE" {
                redundantStops = redundantStops + 1;
            } else {
                state = "IDLE";
            }
        } else if p == "BURST" {
            if state == "IDLE" {
                // dispenses this tick, remains IDLE
            } else {
                // remains DISPENSING
            }
        }

        if state == "DISPENSING" {
            dispensingTicks = dispensingTicks + 1;
        } else if p == "BURST" {
            dispensingTicks = dispensingTicks + 1;
        }
    }

    let totalTicks: Int = length(presses);
    let idleTicks: Int = totalTicks - dispensingTicks;

    fx {
        println("FinalState=", state);
        println("DispensingTicks=", dispensingTicks);
        println("RedundantStops=", redundantStops);
        println("RedundantFeeds=", redundantFeeds);
        println("IdleTicks=", idleTicks);
    }
    ret;
}

