type Exhibit {
    name: Text = "";
    room: Text = "";
    year: Int = 0;
    onLoan: Bool = false;
    guide: Text = "";
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("exhibits.json"); }
    let root: ToonNode = toon_root(doc);

    let exhibits: Exhibit[] = [];
    let loanCount: Int = 0;

    loop i in 0..toon_len(root) {
        let row: ToonNode = toon_at(root, i);
        let name: Text = toon_get_text_or(row, "name", "");
        let room: Text = toon_get_text_or(row, "room", "");
        let year: Int = toon_get_int_or(row, "year", 0);
        let onLoan: Bool = toon_get_bool_or(row, "onLoan", false);
        let guide: Text = toon_get_text_or(row, "guide", "");
        let e: Exhibit = new Exhibit { name: name, room: room, year: year, onLoan: onLoan, guide: guide };
        exhibits = exhibits + [e];
        if onLoan {
            loanCount = loanCount + 1;
        }
    }

    let sorted: Exhibit[] = sorted_by(exhibits, "year");
    let n: Int = length(sorted);
    loop i in 0..n {
        loop j in i + 1..n {
            if sorted[j].year < sorted[i].year || (sorted[j].year == sorted[i].year && sorted[j].name < sorted[i].name) {
                let tmp: Exhibit = sorted[i];
                sorted[i] = sorted[j];
                sorted[j] = tmp;
            }
        }
    }

    fx {
        println("EXHIBIT REPORT");
        loop i in 0..n {
            let e: Exhibit = sorted[i];
            let loanText: Text = if e.onLoan { "Yes" } else { "No" };
            let guideText: Text = if e.guide == "" { "-" } else { e.guide };
            println(e.name, " | ", e.room, " | ", e.year, " | ", loanText, " | ", guideText);
        }
        println("TOTAL ON LOAN: ", loanCount);
    }

    toon_close(doc);
    ret;
}

