            invalidCount = invalidCount + 1;
            fx {
                println("Invalid order ", orderId, ": ", pages, " pages");
            }
        } else {
            validCount = validCount + 1;
            totalPages = totalPages + pages;
            if rush == "yes" {
                rushCount = rushCount + 1;
            }
        }
    }

    if invalidCount == 0 {
        fx {
            println("No invalid orders");
        }
    }

    fx {
        println("Total valid orders: ", validCount);
        println("Total pages: ", totalPages);
        println("Rush orders: ", rushCount);
    }

    ret;
}

