        if weights[i] < 15.0 {
            hasUnder = true;
        }
        if fruits[i] == "apple" {
            appleCount = appleCount + 1;
        }
        totalWeight = totalWeight + weights[i];
    }

    let avg: Real = 0.0;
    if n > 0 {
        avg = totalWeight / (n * 1.0);
