        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "[{\"id\":\"A1\",\"capacity\":200,\"reading\":{\"ph\":7.2,\"temp\":25.4}},{\"id\":\"A2\",\"capacity\":150,\"reading\":{\"ph\":6.8,\"temp\":24.1}},{\"id\":\"B1\",\"capacity\":300,\"reading\":{\"ph\":7.5,\"temp\":26.0}},{\"id\":\"B2\",\"capacity\":100,\"reading\":{\"ph\":8.1,\"temp\":27.3}}]";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);
    let checkCount: Int = 0;

    loop i in 0..toon_len(root) {
        let tank: ToonNode = toon_at(root, i);
        let id: Text = toon_get_text_or(tank, "id", "?");
        let reading: ToonNode = toon_key_or(tank, "reading", toon_null());
        let ph: Real = toon_get_real_or(reading, "ph", 0.0);
        let temp: Real = toon_get_real_or(reading, "temp", 0.0);
        let status: Text = "CHECK";
        if ph >= 6.5 && ph <= 8.0 && temp >= 23.0 && temp <= 27.0 {
            status = "OK";
        } else {
            checkCount = checkCount + 1;
        }
        fx {
            println(id, " | pH=", format_float(ph, 1), " | Temp=", format_float(temp, 1), " | Status=", status);
        }
    }

    fx {
        println("Tanks needing check: ", checkCount);
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "[{\"name\":\"Chop\",\"type\":\"action\",\"value\":3},{\"name\":\"Wood\",\"type\":\"resource\",\"value\":2},{\"name\":\"Monument\",\"type\":\"victory\",\"value\":4.5},{\"name\":\"Build\",\"type\":\"action\",\"value\":2},{\"name\":\"Stone\",\"type\":\"resource\",\"value\":1},{\"name\":\"Statue\",\"type\":\"victory\",\"value\":6.0},{\"name\":\"Trade\",\"type\":\"action\",\"value\":1.5}]";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);
    let count: Int = toon_len(root);

    fx {
        println("Card count: ", count);
    }

    let realCount: Int = 0;

    loop i in 0..count {
        let card: ToonNode = toon_at(root, i);
        let name: Text = toon_get_text_or(card, "name", "?");
        let cardType: Text = toon_get_text_or(card, "type", "?");
        let valueNode: ToonNode = toon_key_or(card, "value", toon_null());
        let isReal: Bool = toon_is_real(valueNode);
        let valueText: Text;
        let kind: Text;
        if isReal {
            let v: Real = toon_real_value(valueNode);
            if v == int(v) {
                valueText = int_to_text(int(v));
                kind = "INT";
            } else {
                valueText = format_float(v, 1);
                kind = "REAL";
                realCount = realCount + 1;
            }
        } else {
            let v: Int = toon_int_value(valueNode);
            valueText = int_to_text(v);
            kind = "INT";
        }
        fx {
            println(name, " | ", cardType, " | value=", valueText, " | kind=", kind);
        }
    }

    fx {
        println("Mixed value types: ", realCount);
    }

    toon_close(doc);
    ret;
}

