fn main() -> Void {
    let segments: Text[] = ["S1, S4", "S2, S4", "S1, S3", "S3, S4"];
    let order: Text[] = [];
    let segs: Int[][] = [];

    loop s in 0..length(segments) {
        let parts: Text[] = split(segments[s], ",");
        loop p in parts {
            let sig: Text = trim(p);
            if !contains(order, sig) {
                order = order + [sig];
                let empty: Int[] = [];
                segs = segs + [empty];
            }
            let idx: Int = index_of(order, sig);
            segs[idx] = segs[idx] + [s + 1];
        }
    }

    loop i in 0..length(order) {
        let nums: Int[] = [];
        loop n in segs[i] {
            nums = nums + [n];
        }
        let sorted: Int[] = sorted(nums);
        let parts: Text[] = [];
        loop n in sorted {
            parts = parts + [int_to_text(n)];
        }
        let list: Text = join(parts, ",");
        fx {
            println(order[i], ": ", list);
        }
    }
    ret;
}

