    loop a in 0..4 {
        loop b in 0..4 {
            if a == 0 && b != 1 && b != 2 {
                continue;
            }
            if a == 2 && b != 0 && b != 3 {
                continue;
            }
            if a == 3 && b != 2 {
                continue;
            }
            loop c in 0..4 {
                if b == 0 && c != 1 && c != 2 {
                    continue;
                }
                if b == 2 && c != 0 && c != 3 {
                    continue;
                }
                if b == 3 && c != 2 {
                    continue;
                }
                loop d in 0..4 {
                    if c == 0 && d != 1 && d != 2 {
                        continue;
                    }
                    if c == 2 && d != 0 && d != 3 {
                        continue;
                    }
                    if c == 3 && d != 2 {
                        continue;
