fn main() -> Void {
    let grid: Int[][] = [
        [5, 5, 0, 3],
        [5, 0, 0, 3],
        [0, 0, 4, 4],
        [0, 7, 7, 0]
    ];
    let rows: Int = 4;
    let cols: Int = 4;
    let visited: Bool[][] = [[false; cols]; rows];
    let regionCount: Int = 0;
    let blockedCount: Int = 0;
    let regionLines: Text[] = [];

    loop r in 0..rows {
        loop c in 0..cols {
            if grid[r][c] == 0 {
                blockedCount = blockedCount + 1;
            } else if !visited[r][c] {
                regionCount = regionCount + 1;
                let size: Int = 0;
                let total: Int = 0;
                let stack: Int[] = [r * cols + c];
                visited[r][c] = true;
                loop stack.length > 0 {
                    let code: Int = stack[stack.length - 1];
                    stack = stack[..stack.length - 1];
                    let cr: Int = code div cols;
                    let cc: Int = code % cols;
                    size = size + 1;
                    total = total + grid[cr][cc];
                    if cr > 0 && !visited[cr - 1][cc] && grid[cr - 1][cc] > 0 {
                        visited[cr - 1][cc] = true;
                        stack = stack + [(cr - 1) * cols + cc];
                    }
                    if cr < rows - 1 && !visited[cr + 1][cc] && grid[cr + 1][cc] > 0 {
                        visited[cr + 1][cc] = true;
                        stack = stack + [(cr + 1) * cols + cc];
                    }
                    if cc > 0 && !visited[cr][cc - 1] && grid[cr][cc - 1] > 0 {
                        visited[cr][cc - 1] = true;
                        stack = stack + [cr * cols + (cc - 1)];
                    }
                    if cc < cols - 1 && !visited[cr][cc + 1] && grid[cr][cc + 1] > 0 {
                        visited[cr][cc + 1] = true;
                        stack = stack + [cr * cols + (cc + 1)];
                    }
                }
                regionLines = regionLines + ["REGION " + int_to_text(regionCount) + " " + int_to_text(size) + " " + int_to_text(total)];
            }
        }
    }

    fx {
        println("REGIONS " + int_to_text(regionCount));
        loop line in regionLines {
            println(line);
        }
        println("BLOCKED " + int_to_text(blockedCount));
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [1, 0, 1, 1, 0],
        [1, 1, 0, 1, 1],
        [0, 1, 1, 0, 1],
        [1, 1, 1, 1, 0]
    ];

    let totalOccupied: Int = 0;
    let totalFree: Int = 0;
    let clusterLevels: Int = 0;
    let rows: Int = length(grid);
    let cols: Int = length(grid[0]);

    loop r in 0..rows {
        let row: Int[] = grid[r];
        let occ: Int = 0;
        let free: Int = 0;
        loop c in 0..cols {
            if row[c] == 1 {
                occ = occ + 1;
            } else {
                free = free + 1;
            }
        }
        totalOccupied = totalOccupied + occ;
        totalFree = totalFree + free;

        let hasCluster: Bool = false;
        loop c in 0..cols {
            if row[c] == 1 {
                if c + 1 < cols && row[c + 1] == 1 {
                    hasCluster = true;
                }
                if r + 1 < rows && grid[r + 1][c] == 1 {
                    hasCluster = true;
                }
            }
        }
        if hasCluster {
            clusterLevels = clusterLevels + 1;
        }
    }

    let totalSpots: Int = rows * cols;
    let avg: Real = totalOccupied * 1.0 / totalSpots * 100.0;

    fx {
        println("TOTAL_OCCUPIED ", totalOccupied);
        println("TOTAL_FREE ", totalFree);
        loop r in 0..rows {
            let row: Int[] = grid[r];
            let occ: Int = 0;
            let free: Int = 0;
            loop c in 0..cols {
                if row[c] == 1 {
                    occ = occ + 1;
                } else {
                    free = free + 1;
                }
            }
            println("LEVEL ", r, " ", occ, " ", free);
        }
        println("CLUSTER_LEVELS ", clusterLevels);
        println("AVG_OCCUPANCY ", format_float(avg, 2));
    }

    ret;
}

@pure
fn to_base4(n: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let digits: Int[] = [];
    let v: Int = n;
    loop {
        let d: Int = v % 4;
        digits = digits + [d];
        v = v div 4;
        if v == 0 {
            break;
        }
    }
    let result: Text = "";
    loop i in 0..length(digits) {
        let d: Int = digits[length(digits) - 1 - i];
        if d < 10 {
            result = result + int_to_text(d);
        } else {
            result = result + chr(65 + d - 10);
        }
    }
    ret result;
}

fn main() -> Void {
    let orders: Int[] = [10, 25, 64, 100, 7];
    loop i in 0..length(orders) {
        let n: Int = orders[i];
        let b4: Text = to_base4(n);
        let even: Bool = n % 2 == 0;
        fx {
            println("ORDER ", n, " BASE4 ", b4, " EVEN ", even);
        }
    }
    ret;
}

fn main() -> Void {
    let ring: Int[] = [];
    let resCount: Int = 0;
    let overwritten: Int = 0;

    let ops: Text[] = [
        "RES 10",
        "RES 20",
        "RES 30",
        "REL",
        "RES 40",
        "RES 50",
        "REL",
        "RES 60",
        "REL",
        "RES 70",
        "REL"
    ];

    loop op in ops {
        let parts: Text[] = split(op, " ");
        let action: Text = parts[0];
        if action == "RES" {
            let resident: Int = parse_int(parts[1]);
            resCount = resCount + 1;
            if length(ring) >= 4 {
                ring = ring[1..];
                overwritten = overwritten + 1;
            }
            ring = ring + [resident];
        } else if action == "REL" {
            if length(ring) > 0 {
                ring = ring[1..];
            }
        }
    }

    fx {
        let line: Text = "Ring contents (oldest to newest): ";
        loop i in 0..length(ring) {
            if i > 0 {
                line = line + " ";
            }
            line = line + int_to_text(ring[i]);
        }
        println(line);
        println("Reservations made: ", resCount);
        println("Overwritten entries: ", overwritten);
    }
    ret;
}

fn main() -> Void {
    let lines: Text[] = [
        "CODE=E1;WING=north;DUR=180",
        "CODE=E2;WING=north;DUR=240",
        "CODE=E3;WING=south;DUR=150",
        "CODE=E4;WING=south;DUR=300",
        "CODE=E5;WING=east;DUR=210",
        "CODE=E6;WING=north;DUR=180"
    ];

    let wings: Text[] = [];
    let totals: Int[] = [];

    loop line in lines {
        let parts: Text[] = split(line, ";");
        let wing: Text = "";
        let dur: Int = 0;
        loop p in parts {
            let kv: Text[] = split(p, "=");
            if kv[0] == "WING" {
                wing = kv[1];
            }
            if kv[0] == "DUR" {
                dur = parse_int(kv[1]);
            }
        }
        let found: Bool = false;
        loop i in 0..length(wings) {
            if wings[i] == wing {
                found = true;
                totals[i] = totals[i] + dur;
            }
        }
        if !found {
            wings = wings + [wing];
            totals = totals + [dur];
        }
    }

    let sortedWings: Text[] = sorted(wings);
    let sortedTotals: Int[] = [];
    loop w in sortedWings {
        loop i in 0..length(wings) {
            if wings[i] == w {
                sortedTotals = sortedTotals + [totals[i]];
            }
        }
    }

    loop i in 0..length(sortedWings) {
        let minutes: Real = sortedTotals[i] * 1.0 / 60.0;
        let rounded: Real = round_to(minutes, 2);
        fx {
            println(sortedWings[i], " min=", format_float(rounded, 2));
        }
    }
    ret;
}

