        "DEST=durham;TIME=09:00;PLATFORM=1;DELAY=0",
        "DEST=durham;TIME=10:20;PLATFORM=2;DELAY=3",
        "DEST=leeds;TIME=11:00;PLATFORM=4;DELAY=0"
    ];

    let dests: Text[] = [];
    let delays: Int[] = [];

    loop line in lines {
        let parts: Text[] = split(line, ";");
        let destPart: Text = parts[0];
        let delayPart: Text = parts[3];
        let dest: Text = destPart[5..];
        let delay: Int = parse_int(delayPart[6..]);
        dests = dests + [dest];
        delays = delays + [delay];
    }

    let unique: Text[] = [];
    loop d in dests {
        if !contains(unique, d) {
            unique = unique + [d];
        }
    }
    let sorted: Text[] = sorted(unique);

    loop dest in sorted {
        let total: Int = 0;
        let count: Int = 0;
        loop i in 0..length(dests) {
            if dests[i] == dest {
                total = total + delays[i];
                count = count + 1;
            }
        }
        let avg: Real = total * 1.0 / count;
        let rounded: Real = round_to(avg, 2);
        fx {
            println(dest, " avg_delay=", format_float(rounded, 2));
        }
    }
    ret;
}

fn main() -> Void {
    let m1: Int[] = [];
    let m2: Int[] = [];

    let reqs: Int[][] = [
        [1, 0, 45],
        [1, 30, 75],
        [2, 10, 55],
        [2, 50, 90],
        [1, 50, 95],
        [2, 60, 100]
    ];

    loop i in 0..length(reqs) {
        let req: Int[] = reqs[i];
        let machine: Int = req[0];
        let start: Int = req[1];
        let end: Int = req[2];
        let ok: Bool = true;

        if machine == 1 {
            loop j in 0..length(m1) step 2 {
                let s: Int = m1[j];
                let e: Int = m1[j + 1];
                if start < e && s < end {
                    ok = false;
                    break;
                }
            }
            if ok {
                m1 = m1 + [start, end];
            }
        } else {
            loop j in 0..length(m2) step 2 {
                let s: Int = m2[j];
                let e: Int = m2[j + 1];
                if start < e && s < end {
                    ok = false;
                    break;
                }
            }
            if ok {
                m2 = m2 + [start, end];
            }
        }

        if ok {
            fx {
                println("Request ", i + 1, " accepted");
            }
        } else {
            fx {
                println("Request ", i + 1, " rejected");
            }
        }
    }

    ret;
}

fn main() -> Void {
