    let count: Int = 0;

    loop i in 0..length(docks) {
        loop j in i + 1..length(docks) {
            if docks[i] != docks[j] {
                let swapped: Text[] = [docks[0], docks[1], docks[2], docks[3]];
                let tmp: Text = swapped[i];
                swapped[i] = swapped[j];
                swapped[j] = tmp;
                let key: Text = swapped[0] + swapped[1] + swapped[2] + swapped[3];
                if !has(seen, key) {
                    seen[key] = true;
                    count = count + 1;
                }
            }
        }
    }

    fx {
        println("Distinct arrangements: ", count);
    }
    ret;
}

