fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("line_delays.json"); }
    let root: ToonNode = toon_root(doc);

    let total: Int = toon_len(root);
    let totalDelayed: Int = 0;
    let fullyOnTime: Int = 0;

    let bestLine: Text = "";
    let bestRate: Real = -1.0;
    let worstLine: Text = "";
    let worstDelay: Int = -1;

    loop i in 0..total {
        let row: ToonNode = toon_at(root, i);
        let line: Text = toon_get_text_or(row, "line", "");
        let scheduled: Int = toon_get_int_or(row, "scheduled_trains", 0);
        let delayed: Int = toon_get_int_or(row, "delayed_trains", 0);
        let worst: Int = toon_get_int_or(row, "worst_delay_min", 0);

        totalDelayed = totalDelayed + delayed;
        if delayed == 0 {
            fullyOnTime = fullyOnTime + 1;
        }

        if scheduled > 0 {
            let rate: Real = (scheduled - delayed) * 100.0 / scheduled;
            if rate > bestRate || (rate == bestRate && line < bestLine) {
                bestRate = rate;
                bestLine = line;
            }
        }

        if worst > worstDelay || (worst == worstDelay && line < worstLine) {
            worstDelay = worst;
            worstLine = line;
        }
    }

    fx {
        println("Lines: ", total);
        println("Total delayed: ", totalDelayed);
        println("Best on-time rate: ", bestLine, " ", format_float(bestRate, 1));
        println("Worst delay: ", worstLine);
        println("Lines fully on time: ", fullyOnTime);
    }

    toon_close(doc);
    ret;
}

