    let wettestId: Text = "";
    let wettestRain: Int = -1;
    let sumRain: Int = 0;
    let sumDays: Int = 0;
    let snowCount: Int = 0;
    let driestId: Text = "";
    let driestRatio: Real = 0.0;
    let hasDriest: Bool = false;

