fn main() -> Void {
    let suits: Text[] = ["HEART", "SPADE", "DIAMOND", "CLUB", "HEART", "SPADE", "DIAMOND", "CLUB", "HEART", "SPADE", "DIAMOND", "CLUB", "HEART", "SPADE", "DIAMOND", "CLUB"];
    let names: Text[] = ["CLUB", "DIAMOND", "HEART", "SPADE"];
    let counts: Int[] = [0, 0, 0, 0];
    loop s in suits {
        loop i in 0..4 {
            if s == names[i] {
                counts[i] = counts[i] + 1;
            }
        }
    }
    // sort by count desc, then name asc (names already alphabetical)
    let order: Int[] = [0, 1, 2, 3];
    loop i in 0..4 {
        loop j in 0..3 {
            if counts[order[j]] < counts[order[j + 1]] {
                let tmp: Int = order[j];
                order[j] = order[j + 1];
                order[j + 1] = tmp;
            }
        }
    }
    fx {
        loop k in 0..4 {
            println(names[order[k]], ": ", counts[order[k]]);
        }
    }
    ret;
}

