fn main() -> Void {
    let orders: Text[] = ["LOAF", "CROISSANT", "BAGEL", "LOAF", "MUFFIN", "CROISSANT", "LOAF", "BAGEL", "MUFFIN", "LOAF", "CROISSANT", "BAGEL", "MUFFIN"];
    let types: OrderType[] = [];

    loop order in orders {
        let found: Bool = false;
        loop t in types {
            if t.name == order {
                t.count = t.count + 1;
                found = true;
                break;
            }
        }
        if !found {
            types = types + [new OrderType { name: order, count: 1 }];
        }
    }

    let sorted: OrderType[] = sorted_by_desc(types, "count");

    let n: Int = length(sorted);
    loop i in 0..n {
        let j: Int = i + 1;
        while j < n {
            if sorted[i].count == sorted[j].count && sorted[i].name > sorted[j].name {
                let tmp: OrderType = sorted[i];
                sorted[i] = sorted[j];
                sorted[j] = tmp;
            }
            j = j + 1;
        }
    }

    fx {
        loop t in sorted {
            println(t.name, " - ", t.count);
        }
    }
    ret;
}

