    let n: Int = length(prefs);
    let best: Int = 0;

    loop mask in 0..(1 << n) {
        let rowA: Int = 0;
        let rowB: Int = 0;
        let satisfied: Int = 0;

        loop i in 0..n {
            let bit: Int = (mask >> i) & 1;
            if bit == 1 {
                rowA = rowA + 1;
                if prefs[i] == "A" {
                    satisfied = satisfied + 1;
                }
            } else {
                rowB = rowB + 1;
                if prefs[i] == "B" {
                    satisfied = satisfied + 1;
                }
            }
        }

        if rowA >= 1 && rowA <= 3 && rowB >= 1 && rowB <= 3 {
            if satisfied > best {
                best = satisfied;
            }
        }
    }

    fx {
        println("Max Satisfied: ", best);
    }
    ret;
}

