fn to_base8(n: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let digits: Int[] = [];
    let v: Int = n;
    loop {
        let d: Int = v % 8;
        digits = digits + [d];
        v = v div 8;
        if v == 0 {
            break;
        }
    }
    let s: Text = "";
    loop i in 0..length(digits) {
        s = s + int_to_text(digits[length(digits) - 1 - i]);
    }
    ret s;
}

