fn main() -> Void {
    let readings: Int[] = [2, 5, 0, 3, 7, 1, 4, 6, 2, 0];
    let capacity: Int = 4;
    let buffer: Int[] = [0, 0, 0, 0];
    let count: Int = 0;
    let overwrites: Int = 0;
    let largestOverwritten: Int = 0;
    let hasOverwrite: Bool = false;

    loop r in readings {
        if count < capacity {
            buffer[count] = r;
            count = count + 1;
        } else {
            let oldest: Int = buffer[0];
            if !hasOverwrite || oldest > largestOverwritten {
                largestOverwritten = oldest;
                hasOverwrite = true;
            }
            overwrites = overwrites + 1;
            loop i in 1..capacity {
                buffer[i - 1] = buffer[i];
            }
            buffer[capacity - 1] = r;
        }
    }

    let total: Int = 0;
    loop i in 0..capacity {
        total = total + buffer[i];
    }

    let contents: Text = int_to_text(buffer[0]);
    loop i in 1..capacity {
        contents = contents + ", " + int_to_text(buffer[i]);
    }

    let largestText: Text = "none";
    if hasOverwrite {
        largestText = int_to_text(largestOverwritten);
    }

    fx {
        println("Readings processed: ", length(readings));
        println("Overwrites: ", overwrites);
        println("Buffer contents: ", contents);
        println("Buffer sum: ", total);
        println("Largest overwritten value: ", largestText);
    }
    ret;
}

fn main() -> Void {
