    let overwrites: Int = 0;
    let largestOverwritten: Int = 0;
    let hasOverwrite: Bool = false;

    loop i in 0..length(coins) {
        let val: Int = coins[i];
        if count < capacity {
            ring[count] = val;
            count = count + 1;
        } else {
            let oldest: Int = ring[0];
            ring[0] = ring[1];
            ring[1] = ring[2];
            ring[2] = val;
            overwrites = overwrites + 1;
            if !hasOverwrite || oldest > largestOverwritten {
                largestOverwritten = oldest;
                hasOverwrite = true;
            }
        }
    }

    let ringTotal: Int = ring[0] + ring[1] + ring[2];
    let largestText: Text = if hasOverwrite { int_to_text(largestOverwritten) } else { "none" };

    fx {
        println("Coins inserted: ", length(coins));
        println("Overwrites: ", overwrites);
        println("Ring contents: ", ring[0], ", ", ring[1], ", ", ring[2]);
        println("Ring total: ", ringTotal);
        println("Largest overwritten value: ", largestText);
    }
    ret;
}

