    let totalSeconds: Int = 0;

    loop line in lines {
        let parts: Text[] = split(line, " ");
        if parts[0] == "PASS" {
            passed = passed + 1;
            totalSeconds = totalSeconds + parse_int(parts[3]);
        } else if parts[0] == "DROP" {
            dropped = dropped + 1;
        }
    }

    fx {
        println("Passed: ", passed);
        println("Dropped: ", dropped);
        loop line in lines {
            let parts: Text[] = split(line, " ");
            if parts[0] == "PASS" {
                println("Bib ", parts[1], " -> ", parts[2]);
            }
        }
        let avg: Real = totalSeconds * 1.0 / passed;
        println("Avg seconds: ", format_float(avg, 1));
    }

    ret;
}

