fn main() -> Void {
    let grid: Int[][] = [
        [-5, -7, -4],
        [-6, -8, -3],
        [-2, -5, -6]
    ];

    let total: Int = 0;
    let minVal: Int = 0;
    let minRow: Int = 0;
    let minCol: Int = 0;
    let first: Bool = true;

    loop r in 0..3 {
        loop c in 0..3 {
            let v: Int = grid[r][c];
            total = total + v;
            if first {
                minVal = v;
                minRow = r;
                minCol = c;
                first = false;
            } else {
                if v < minVal {
                    minVal = v;
                    minRow = r;
                    minCol = c;
                }
            }
        }
    }

    let rounded: Int[][] = [];
    loop r in 0..3 {
        let row: Int[] = [];
        loop c in 0..3 {
            let v: Int = grid[r][c];
            let m: Int = v % 3;
            let up: Int = 0;
            let rv: Int = 0;
            if m == 0 {
                rv = v;
            } else {
                if m > 0 {
                    rv = v + (3 - m);
                } else {
                    rv = v - m;
                }
            }
            row = row + [rv];
        }
        rounded = rounded + [row];
    }

    fx {
        println("SUM ", total);
        println("COLDEST row ", minRow + 1, " col ", minCol + 1);
        println("ROUNDED");
        loop r in 0..3 {
            let line: Text = "";
            loop c in 0..3 {
                if c > 0 {
                    line = line + " ";
                }
                line = line + int_to_text(rounded[r][c]);
            }
            println(line);
        }
    }
    ret;
}

