fn main() -> Void {
    let durations: Int[] = [7, 12, 5, 5, 18, 22, 9, 9, 9, 14, 3, 3, 11];
    let n: Int = length(durations);

    let maxSum: Int = durations[0] + durations[1];
    let maxIdx: Int = 0;
    let minSum: Int = durations[0] + durations[1];
    let minIdx: Int = 0;
    let equalCount: Int = 0;
    let lastIncrease: Int = -1;

    loop i in 0..n - 1 {
        let s: Int = durations[i] + durations[i + 1];
        if s > maxSum {
            maxSum = s;
            maxIdx = i;
        }
        if s < minSum {
            minSum = s;
            minIdx = i;
        }
        if durations[i] == durations[i + 1] {
            equalCount = equalCount + 1;
        }
        if durations[i + 1] > durations[i] {
            lastIncrease = i + 1;
        }
    }

    fx {
        println("Max pair sum: ", maxSum, " at index ", maxIdx);
        println("Min pair sum: ", minSum, " at index ", minIdx);
        println("Equal adjacent pairs: ", equalCount);
        println("Last increase at index: ", lastIncrease);
    }
    ret;
}

