fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "{\"recipes\":[{\"name\":\"Pancakes\",\"base_servings\":4,\"items\":[{\"ingredient\":\"flour\",\"amount\":2.5},{\"ingredient\":\"milk\",\"amount\":1.75}]},{\"name\":\"Curry\",\"base_servings\":6,\"items\":[{\"ingredient\":\"rice\",\"amount\":3.0},{\"ingredient\":\"coconut\",\"amount\":2.25}]},{\"name\":\"Cookies\",\"base_servings\":12,\"items\":[{\"ingredient\":\"sugar\",\"amount\":1.5},{\"ingredient\":\"butter\",\"amount\":2.0}]}],\"target_servings\":[6,4,24]}";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);
    let recipes: ToonNode = toon_key(root, "recipes");
    let targets: ToonNode = toon_key(root, "target_servings");

    fx {
        println("Recipe | Ingredient | Scaled");
    }

    loop i in 0..toon_len(recipes) {
        let recipe: ToonNode = toon_at(recipes, i);
        let name: Text = toon_get_text_or(recipe, "name", "");
        let base: Int = toon_get_int_or(recipe, "base_servings", 1);
        let target: Int = toon_int_value(toon_at(targets, i));
        let items: ToonNode = toon_key(recipe, "items");
        let factor: Real = target * 1.0 / base;

        loop j in 0..toon_len(items) {
            let item: ToonNode = toon_at(items, j);
            let ingredient: Text = toon_get_text_or(item, "ingredient", "");
            let amount: Real = toon_get_real_or(item, "amount", 0.0);
            let scaled: Real = amount * factor;
            fx {
                println(name, " | ", ingredient, " | ", format_float(scaled, 2));
            }
        }
    }

    toon_close(doc);
    ret;
}

