fn main() -> Void {
    let lines: Text[];
    fx { lines = read_lines("shipments.txt"); }

    let localHeavy: Int = 0;
    let remoteLight: Int = 0;
    let invalid: Int = 0;
    let totalPackages: Int = 0;

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        if length(parts) < 3 {
            invalid = invalid + 1;
            continue;
        }
        let id: Text = parts[0];
        let zone: Text = parts[1];
        let count: Int = parse_int(parts[2]);
        if count < 0 {
            invalid = invalid + 1;
            continue;
        }
        let dist: Text = "remote";
        if zone == "Zone A" or zone == "Zone B" {
            dist = "local";
        }
        let weight: Text = "LIGHT";
        if count > 50 {
            weight = "HEAVY";
        }
        if dist == "local" and weight == "HEAVY" {
            localHeavy = localHeavy + 1;
        }
        if dist == "remote" and weight == "LIGHT" {
            remoteLight = remoteLight + 1;
        }
        totalPackages = totalPackages + count;
        fx {
            println(id, " ", dist, " ", weight);
        }
    }

    fx {
        println("Local heavy: ", localHeavy);
        println("Remote light: ", remoteLight);
        println("Invalid: ", invalid);
        println("Total packages: ", totalPackages);
    }
    ret;
}

