fn main() -> Void {
    let callTypes: Text[] = ["Alarm", "Medical", "Alarm", "Rescue", "Medical", "Alarm", "Medical", "Rescue", "Alarm", "Medical", "Rescue", "Alarm", "Medical"];
    let counts: Map[Text, Int] = {};
    loop t in callTypes {
        counts[t] = get(counts, t, 0) + 1;
    }
    let types: Text[] = keys(counts);
    let sortedTypes: Text[] = sorted(types);
    let n: Int = length(sortedTypes);
    let order: Int[] = [];
    loop i in 0..n {
        order = order + [i];
    }
    loop i in 0..n {
        let maxIdx: Int = i;
        loop j in i + 1..n {
            let ci: Int = counts[sortedTypes[order[i]]];
            let cj: Int = counts[sortedTypes[order[j]]];
            if cj > ci {
                maxIdx = j;
            } else if cj == ci && sortedTypes[order[j]] < sortedTypes[order[i]] {
                maxIdx = j;
            }
        }
        let tmp: Int = order[i];
        order[i] = order[maxIdx];
        order[maxIdx] = tmp;
    }
    loop i in 0..n {
        let t: Text = sortedTypes[order[i]];
        let c: Int = counts[t];
        fx {
            println(t, ": ", c);
        }
    }
    ret;
}

