        if cur == 5 {
            count = count + 1;
            if steps + 1 < bestSteps {
                bestSteps = steps + 1;
                bestPath = path;
            }
            ret;
        }
        if cur + 1 <= 5 && !closed[cur + 1] {
            let nextPath: Int[] = path + [cur + 1];
            dfs(cur + 1, steps + 1, nextPath);
        }
        if cur + 2 <= 5 && !closed[cur + 2] {
            let nextPath: Int[] = path + [cur + 2];
            dfs(cur + 2, steps + 1, nextPath);
        }
        ret;
    }

    let startPath: Int[] = [1];
    dfs(1, 0, startPath);

    let pathText: Text = "";
    loop i in 0..length(bestPath) {
        if i > 0 {
            pathText = pathText + ",";
