fn main() -> Void {
    let count: Int = 0;
    let bestBlocks: Int = 99;
    let bestSizes: Int[] = [];

    fn tryBlocks(remaining: Int, current: Int[], depth: Int) -> Void {
        if remaining == 0 {
            count = count + 1;
            if depth < bestBlocks {
                bestBlocks = depth;
                bestSizes = current;
            }
            ret;
        }
        if remaining == 1 {
            let next: Int[] = current + [1];
            tryBlocks(0, next, depth + 1);
            ret;
        }
        if remaining >= 2 {
            let next1: Int[] = current + [1];
            tryBlocks(remaining - 1, next1, depth + 1);
            let next2: Int[] = current + [2];
            tryBlocks(remaining - 2, next2, depth + 1);
            ret;
        }
        ret;
    }

    let start: Int[] = [];
    tryBlocks(4, start, 0);

    let sizesText: Text = "";
    loop i in 0..length(bestSizes) {
        if i > 0 {
            sizesText = sizesText + ",";
        }
        sizesText = sizesText + int_to_text(bestSizes[i]);
    }

    fx {
        println("Sequences: ", count);
        println("FewestBlocks: ", bestBlocks);
        println("BlockSizes: ", sizesText);
    }
    ret;
}

