    let total: Int = 0;
    let perishable: Int = 0;
    let scheduled: Int = 0;
    let lowStock: Int = 0;
    let totalValue: Real = 0.0;
    let cheapestItem: Text = "";
    let cheapestCost: Real = 0.0;
    let largestItem: Text = "";
    let largestQty: Real = 0.0;
    let first: Bool = true;

    loop i in 0..toon_len(root) {
        let row: ToonNode = toon_at(root, i);
        let item: Text = toon_get_text_or(row, "item", "");
        let quantity: Real = toon_get_real_or(row, "quantity", 0.0);
        let unitCost: Real = toon_get_real_or(row, "unit_cost", 0.0);
