        }
        if hasRestock {
            scheduled = scheduled + 1;
        }
        if quantity < 5.0 {
            lowStock = lowStock + 1;
        }
        totalValue = totalValue + quantity * unitCost;

        if first {
            cheapestItem = item;
            cheapestCost = unitCost;
            largestItem = item;
            largestQty = quantity;
            first = false;
