type Swatch {
    name: Text = "";
    brightness: Real = 0.0;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let json: Text = "[{\"name\":\"Crimson\",\"r\":220,\"g\":50,\"b\":60},{\"name\":\"Slate\",\"r\":90,\"g\":100,\"b\":110},{\"name\":\"Mint\",\"r\":140,\"g\":210,\"b\":170},{\"name\":\"Amber\",\"r\":245,\"g\":180,\"b\":40},{\"name\":\"Indigo\",\"r\":60,\"g\":40,\"b\":160}]";
    let doc: ToonDoc = toon_parse(json);
    let root: ToonNode = toon_root(doc);

    let swatches: Swatch[] = [];
    loop i in 0..toon_len(root) {
        let row: ToonNode = toon_at(root, i);
        let name: Text = toon_get_text_or(row, "name", "");
        let r: Int = toon_get_int_or(row, "r", 0);
        let g: Int = toon_get_int_or(row, "g", 0);
        let b: Int = toon_get_int_or(row, "b", 0);
        let brightness: Real = (r + g + b) * 1.0 / 3.0;
        swatches = swatches + [new Swatch { name: name, brightness: brightness }];
    }

    let n: Int = length(swatches);
    loop i in 0..n {
        let minIdx: Int = i;
        loop j in i + 1..n {
            if swatches[j].brightness < swatches[minIdx].brightness {
                minIdx = j;
            }
        }
        if minIdx != i {
            let tmp: Swatch = swatches[i];
            swatches[i] = swatches[minIdx];
            swatches[minIdx] = tmp;
        }
    }

    loop s in swatches {
        fx {
            println(s.name, ": ", format_float(s.brightness, 1));
        }
    }

    toon_close(doc);
    ret;
}

