        entries = entries + [e];
    }

    let n: Int = length(entries);
    loop i in 0..n {
        let j: Int = i + 1;
        loop k in j..n {
            if entries[k].count > entries[i].count || (entries[k].count == entries[i].count && entries[k].name < entries[i].name) {
                let tmp: Visitor = entries[i];
                entries[i] = entries[k];
                entries[k] = tmp;
            }
        }
    }

    fx {
