fn main() -> Void {
    let docks: Int[] = [3, 5, 4, 6, 2, 7, 3, 4];
    let n: Int = length(docks);
    let target: Int = 24;
    let ways: Int = 0;

    // dp[i][s] = number of ways to reach station i (0-indexed) with total dock sum s
    // stations are 0..7, target sum 24
    // max possible sum is sum of all docks = 3+5+4+6+2+7+3+4 = 34
    let maxSum: Int = 35;
    let dp: Int[][] = [];
    loop i in 0..n {
        let row: Int[] = [0; maxSum];
        dp = dp + [row];
    }

    // base case: start at station 0 (index 0)
    dp[0][docks[0]] = 1;

    // transition: from station i, can go to i+1 or i+2
    loop i in 0..n {
        loop s in 0..maxSum {
            if dp[i][s] > 0 {
                let next1: Int = i + 1;
                if next1 < n {
                    let newSum1: Int = s + docks[next1];
                    if newSum1 < maxSum {
                        dp[next1][newSum1] = dp[next1][newSum1] + dp[i][s];
                    }
                }
                let next2: Int = i + 2;
                if next2 < n {
                    let newSum2: Int = s + docks[next2];
                    if newSum2 < maxSum {
                        dp[next2][newSum2] = dp[next2][newSum2] + dp[i][s];
                    }
                }
            }
        }
    }

    ways = dp[n - 1][target];

    fx {
        println("WaysToReach24: ", ways);
    }
    ret;
}

