    let cards: Text[] = ["SSS-SS-SS-", "-SSS-SSSS-", "SSSSSSSS--", "S-S-S-S-S-", "SSSS-SSSSS", "--S--S--S-", "SSSSSSSSSS", "S-S-S-S-S-S"];

    loop card in cards {
        let count: Int = 0;
        loop ch in card {
            if ch == "S" {
                count = count + 1;
            }
        }
        let verdict: Text = if count >= 8 { "FREE DRINK" } else { "NO REWARD" };
        let countText: Text = int_to_text(count);
        let paddedCount: Text = if count < 10 { " " + countText } else { countText };
        let paddedVerdict: Text = verdict + "          ";
        let line: Text = card + " " + paddedCount + " " + paddedVerdict;
        let trimmed: Text = line;
        let len: Int = string_len(trimmed);
        let end: Int = len;
        loop i in 0..len {
            if trimmed[i] == " " {
                end = i;
            } else {
                break;
            }
        }
        // The above loop is wrong for trimming trailing spaces. Let's do it properly.
        let trimmedLine: Text = line;
        let tLen: Int = string_len(trimmedLine);
        let lastNonSpace: Int = tLen - 1;
        loop i in 0..tLen {
            if trimmedLine[i] != " " {
                lastNonSpace = i;
            }
        }
        let finalLine: Text = trimmedLine[0..lastNonSpace + 1];
        fx {
            println(finalLine);
        }
    }
    ret;
}

fn main() -> Void {
    let codes: Text[] = ["111112", "234567", "123454", "999999", "000000", "456789", "111113", "246813"];
    loop code in codes {
        let sum: Int = 0;
        loop i in 0..6 {
            let ch: Text = code[i];
            let d: Int = ord(ch) - ord("0");
            sum = sum + d;
        }
        let sixth: Int = ord(code[5]) - ord("0");
        let valid: Bool = sum == sixth * 3;
        let verdict: Text = if valid { "VALID" } else { "INVALID" };
        let sumText: Text = int_to_text(sum);
        let pad: Int = 3 - string_len(sumText);
        let prefix: Text = "";
        loop p in 0..pad {
            prefix = prefix + " ";
        }
        let line: Text = code + " " + prefix + sumText + " " + verdict;
        fx {
            println(line);
        }
    }
    ret;
}

