fn main() -> Void {
    let log: Text[] = [
        "Red;MOVE;4",
        "Red;COLLECT;10",
        "Blue;MOVE;2",
        "Blue;TRADE;3",
        "Green;COLLECT;7",
        "Red;TRADE;5",
        "Blue;COLLECT;12",
        "Green;MOVE;6",
        "Green;TRADE;2"
    ];

    let redScore: Int = 0;
    let blueScore: Int = 0;
    let greenScore: Int = 0;
    let totalSteps: Int = 0;
    let totalCollected: Int = 0;

    loop line in log {
        let parts: Text[] = split(line, ";");
        let player: Text = parts[0];
        let action: Text = parts[1];
        let value: Int = parse_int(parts[2]);

        if action == "MOVE" {
            totalSteps = totalSteps + value;
        } else if action == "COLLECT" {
            totalCollected = totalCollected + value;
            if player == "Red" {
                redScore = redScore + value;
            } else if player == "Blue" {
                blueScore = blueScore + value;
            } else if player == "Green" {
                greenScore = greenScore + value;
            }
        } else if action == "TRADE" {
            if player == "Red" {
                redScore = redScore - value;
            } else if player == "Blue" {
                blueScore = blueScore - value;
            } else if player == "Green" {
                greenScore = greenScore - value;
            }
        }
    }

    let maxScore: Int = max(max(redScore, blueScore), greenScore);
    let leaders: Text[] = [];
    if redScore == maxScore {
        leaders = leaders + ["Red"];
    }
    if blueScore == maxScore {
        leaders = leaders + ["Blue"];
    }
    if greenScore == maxScore {
        leaders = leaders + ["Green"];
    }
    let leaderText: Text = join(leaders, " ");

    fx {
        println("Red score: ", redScore);
        println("Blue score: ", blueScore);
        println("Green score: ", greenScore);
        println("Leader: ", leaderText);
        println("Total steps: ", totalSteps);
        println("Total collected: ", totalCollected);
    }
    ret;
}

