}

fn main() -> Void {
    let stands: Int[] = [0, 0];
    let queue: Int[] = [];
    let stand0_jobs: Int = 0;
    let stand1_jobs: Int = 0;
    let stand0_total: Int = 0;
    let last_finish: Int = 0;
    let waited_jobs: Int = 0;

    let pref: Int[] = [0, 0, 1, 0, 1, 1, 0, 1, 0];
    let mins: Int[] = [25, 40, 30, 20, 35, 15, 50, 25, 10];

    loop j in 0..9 {
        let p: Int = pref[j];
        let m: Int = mins[j];
        let start: Int = 0;
        let used: Int = -1;

        if stands[p] == 0 {
            start = 0;
            used = p;
        } else {
            let other: Int = 1 - p;
            if stands[other] == 0 {
                start = 0;
                used = other;
            } else {
                waited_jobs = waited_jobs + 1;
                queue = queue + [j];
                let earliest: Int = min(stands[0], stands[1]);
                let freeStand: Int = 0;
                if stands[0] == earliest {
                    freeStand = 0;
                } else {
                    freeStand = 1;
                }
                start = earliest;
                used = freeStand;
            }
        }

        let finish: Int = start + m;
        stands[used] = finish;
        if used == 0 {
            stand0_jobs = stand0_jobs + 1;
            stand0_total = stand0_total + m;
        } else {
            stand1_jobs = stand1_jobs + 1;
        }
        if finish > last_finish {
            last_finish = finish;
        }
    }

    fx {
        println("stand0_jobs=", stand0_jobs);
        println("stand1_jobs=", stand1_jobs);
        println("stand0_total=", stand0_total);
        println("last_finish=", last_finish);
        println("waited_jobs=", waited_jobs);
    }
    ret;
}

