type Order {
    id: Text = "";
    state: Text = "Received";
}

fn main() -> Void {
    let orders: Order[] = [];
    let pickedUpCount: Int = 0;
    let events: Text[] = ["NEW:A", "NEW:B", "ADVANCE", "ADVANCE", "NEW:C", "ADVANCE", "ADVANCE", "ADVANCE", "ADVANCE", "NEW:D", "ADVANCE", "ADVANCE", "ADVANCE", "NEW:E", "ADVANCE", "ADVANCE", "ADVANCE", "ADVANCE"];

    loop ev in events {
        if ev == "ADVANCE" {
            if length(orders) > 0 {
                let front: Order = orders[0];
                if front.state == "Received" {
                    let anyMaking: Bool = false;
                    loop o in orders {
                        if o.state == "Making" {
                            anyMaking = true;
                        }
                    }
                    if !anyMaking {
                        orders[0].state = "Making";
                    }
                } else if front.state == "Making" {
                    orders[0].state = "Ready";
                } else if front.state == "Ready" {
                    orders = orders[1..];
                    pickedUpCount = pickedUpCount + 1;
                }
            }
        } else {
            let id: Text = ev[4..];
            let newOrder: Order = new Order { id: id, state: "Received" };
            orders = orders + [newOrder];
        }
    }

    let queueStr: Text = "";
    if length(orders) == 0 {
        queueStr = "EMPTY";
    } else {
        loop i in 0..length(orders) {
            if i > 0 {
                queueStr = queueStr + ", ";
            }
            queueStr = queueStr + orders[i].id;
        }
    }

    let frontState: Text = "NONE";
    if length(orders) > 0 {
        frontState = orders[0].state;
    }

    let makingId: Text = "NONE";
    loop o in orders {
        if o.state == "Making" {
            makingId = o.id;
        }
    }

    fx {
        println("Queue: ", queueStr);
        println("FrontState: ", frontState);
        println("Making: ", makingId);
        println("PickedUpCount: ", pickedUpCount);
    }
    ret;
}

