fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("trains.json"); }
    let root: ToonNode = toon_root(doc);

    let cancelled: Int = 0;
    let ids: Text[] = [];
    let lines: Text[] = [];
    let delays: Int[] = [];

    loop i in 0..toon_len(root) {
        let row: ToonNode = toon_at(root, i);
        let sid: Text = toon_get_text_or(row, "service_id", "");
        let line: Text = toon_get_text_or(row, "line", "");
        let scheduled: Int = toon_get_int_or(row, "scheduled", 0);
        if toon_has_key(row, "actual") {
            let actual: Int = toon_get_int(row, "actual");
            let delay: Int = actual - scheduled;
            if delay > 0 {
                ids = ids + [sid];
                lines = lines + [line];
                delays = delays + [delay];
            }
        } else {
            cancelled = cancelled + 1;
        }
    }

    let n: Int = length(ids);
    loop i in 0..n {
        let maxD: Int = delays[i];
        let maxI: Int = i;
        loop j in i + 1..n {
            if delays[j] > maxD || (delays[j] == maxD && ids[j] < ids[maxI]) {
                maxD = delays[j];
                maxI = j;
            }
        }
        if maxI != i {
            let tmpId: Text = ids[i];
            ids[i] = ids[maxI];
            ids[maxI] = tmpId;
            let tmpLine: Text = lines[i];
            lines[i] = lines[maxI];
            lines[maxI] = tmpLine;
            let tmpDelay: Int = delays[i];
            delays[i] = delays[maxI];
            delays[maxI] = tmpDelay;
        }
    }

    fx {
        println("Cancelled: ", cancelled);
        println("");
        loop i in 0..n {
            println(ids[i], " | ", lines[i], " | delay: ", delays[i], " min");
        }
        println("");
        if n > 0 {
            println("Worst delay: ", ids[0]);
        } else {
            println("Worst delay: ");
        }
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("harvest.json"); }
    let root: ToonNode = toon_root(doc);

    let n: Int = toon_len(root);
    let unguarded: Int = 0;
    let totalWeight: Real = 0.0;
    let heaviestId: Text = "";
    let heaviestWeight: Real = 0.0;

    let varieties: Text[] = [];
    let vCounts: Int[] = [];
    let vWeights: Real[] = [];

    loop i in 0..n {
        let row: ToonNode = toon_at(root, i);
        let crateId: Text = toon_get_text_or(row, "crate_id", "");
        let variety: Text = toon_get_text_or(row, "variety", "");
        let weight: Real = toon_get_real_or(row, "weight_kg", 0.0);

        if !toon_has_key(row, "grade") {
            unguarded = unguarded + 1;
        }

        totalWeight = totalWeight + weight;

        if i == 0 || weight > heaviestWeight {
            heaviestWeight = weight;
            heaviestId = crateId;
        }

        let found: Bool = false;
        loop j in 0..length(varieties) {
            if varieties[j] == variety {
                found = true;
                vCounts[j] = vCounts[j] + 1;
                vWeights[j] = vWeights[j] + weight;
                break;
            }
        }
        if !found {
            varieties = varieties + [variety];
            vCounts = vCounts + [1];
            vWeights = vWeights + [weight];
        }
    }

    let sortedIdx: Int[] = [];
    loop i in 0..length(varieties) {
        sortedIdx = sortedIdx + [i];
    }
    loop i in 0..length(sortedIdx) {
        loop j in 0..length(sortedIdx) - i - 1 {
            if varieties[sortedIdx[j]] > varieties[sortedIdx[j + 1]] {
                let tmp: Int = sortedIdx[j];
                sortedIdx[j] = sortedIdx[j + 1];
                sortedIdx[j + 1] = tmp;
            }
        }
    }

    fx {
        println("Unguarded: ", unguarded);
        println("");
        println("Total weight: ", format_float(totalWeight, 1));
        println("");
        loop i in 0..length(sortedIdx) {
            let idx: Int = sortedIdx[i];
            let avg: Real = vWeights[idx] / vCounts[idx];
            println(varieties[idx], ": ", vCounts[idx], " crates, ", format_float(avg, 1), " kg avg");
        }
        println("");
        println("Heaviest: ", heaviestId, " (", format_float(heaviestWeight, 1), " kg)");
    }

    toon_close(doc);
    ret;
}

fn main() -> Void {
    if !has_toon() {
        fx { println("structured data support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx { doc = toon_parse_file("clubs.json"); }
    let root: ToonNode = toon_root(doc);

    let n: Int = toon_len(root);
    let noRoom: Int = 0;
    let inactive: Int = 0;
    let grandTotal: Real = 0.0;

    let names: Text[] = [];
    let revenues: Real[] = [];

    loop i in 0..n {
        let row: ToonNode = toon_at(root, i);
        let name: Text = toon_get_text_or(row, "club_name", "");
        let members: Int = toon_get_int_or(row, "members", 0);
        let fee: Real = toon_get_real_or(row, "fee", 0.0);
        let active: Bool = toon_get_bool_or(row, "active", false);

        if !toon_has_key(row, "room") {
            noRoom = noRoom + 1;
        }
        if !active {
            inactive = inactive + 1;
        }

        let rev: Real = members * fee;
        grandTotal = grandTotal + rev;
        names = names + [name];
        revenues = revenues + [rev];
    }

    let order: Int[] = [];
    loop i in 0..n {
        order = order + [i];
    }

    loop i in 0..n {
        loop j in 0..n - i - 1 {
            let a: Int = order[j];
            let b: Int = order[j + 1];
            let swap: Bool = false;
            if revenues[a] < revenues[b] {
                swap = true;
            } else if revenues[a] == revenues[b] {
                if names[a] > names[b] {
                    swap = true;
                }
            }
            if swap {
                let tmp: Int = order[j];
                order[j] = order[j + 1];
                order[j + 1] = tmp;
            }
        }
    }

    fx {
        println("No room assigned: ", noRoom);
        println("");
        println("Inactive clubs: ", inactive);
        println("");
        loop k in 0..n {
            let idx: Int = order[k];
            println(names[idx], ": ", format_float(revenues[idx], 2), " USD");
        }
        println("");
        println("Grand total: ", format_float(grandTotal, 2));
    }

    toon_close(doc);
    ret;
}

