fn main() -> Void {
    let lines: Text[];
    fx { lines = read_lines("pallets.txt"); }

    let total: Int = 0;
    let frozen: Int = 0;
    let zoneA: Int = 0;
    let hottest: Int = -999999;
    let sumTemp: Int = 0;

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        let pid: Int = parse_int(parts[0]);
        let zone: Text = parts[1];
        let temp: Int = parse_int(parts[2]);
        let flag: Text = parts[3];

        total = total + 1;
        if flag == "Y" {
            frozen = frozen + 1;
        }
        if zone == "A" {
            zoneA = zoneA + 1;
        }
        if temp > hottest {
            hottest = temp;
        }
        sumTemp = sumTemp + temp;
    }

    let avg: Real = 0.0;
    if total > 0 {
        avg = sumTemp * 1.0 / total;
    }

    fx {
        println("Pallets: ", total);
        println("Frozen: ", frozen);
        println("Zone A: ", zoneA);
        println("Hottest: ", hottest);
        println("Avg temp: ", format_float(avg, 2));
    }
