type Plant {
    name: Text = "";
    count: Int = 0;
}

fn main() -> Void {
    let names: Text[] = ["Fern", "Rose", "Fern", "Daisy", "Rose", "Iris", "Daisy", "Fern", "Iris", "Rose", "Moss", "Daisy"];
    let plants: Plant[] = [];

    loop name in names {
        let found: Bool = false;
        loop p in plants {
            if p.name == name {
                p.count = p.count + 1;
                found = true;
                break;
            }
        }
        if !found {
            plants = plants + [new Plant { name: name, count: 1 }];
        }
    }

    let sorted: Plant[] = sorted_by_desc(plants, "count");
    let final: Plant[] = sorted_by(sorted, "name");
    let result: Plant[] = sorted_by_desc(final, "count");

    fx {
        loop p in result {
            println(p.name, ":", p.count);
        }
    }
    ret;
}

fn main() -> Void {
    let readings: Text[] = ["Temperature", "Humidity", "Wind", "Temperature", "Rainfall", "Humidity", "Temperature", "Wind", "Humidity", "Temperature", "Rainfall", "Wind", "Temperature", "Humidity"];
    let counts: Map[Text, Int] = {};
    let order: Text[] = [];

    loop r in readings {
        if !has(counts, r) {
            counts[r] = 0;
            order = order + [r];
        }
        counts[r] = counts[r] + 1;
    }

    let n: Int = length(order);
    let sorted: Text[] = [];
    let used: Bool[] = [false; n];

    loop i in 0..n {
        let best: Int = -1;
        loop j in 0..n {
            if !used[j] {
                if best == -1 {
                    best = j;
                } else {
                    if counts[order[j]] > counts[order[best]] {
                        best = j;
                    }
                }
            }
        }
        sorted = sorted + [order[best]];
        used[best] = true;
    }

    fx {
        loop t in sorted {
            println(t, ":", counts[t]);
        }
    }
    ret;
}

