type ZoneCount {
    name: Text = "";
    count: Int = 0;
}

fn main() -> Void {
    let zones: Text[] = ["Zone A", "Zone B", "Zone A", "Zone C", "Zone B", "Zone A", "Zone C", "Zone B", "Zone A", "Zone C", "Zone B", "Zone A", "Zone C", "Zone B"];
    let counts: Map[Text, Int] = {};
    loop z in zones {
        counts[z] = get(counts, z, 0) + 1;
    }
    let list: ZoneCount[] = [];
    loop k in counts {
        list = list + [new ZoneCount { name: k, count: counts[k] }];
    }
    let n: Int = length(list);
    loop i in 0..n {
        let maxIdx: Int = i;
        loop j in i + 1..n {
            if list[j].count > list[maxIdx].count {
                maxIdx = j;
            } else if list[j].count == list[maxIdx].count && list[j].name < list[maxIdx].name {
                maxIdx = j;
            }
        }
        if maxIdx != i {
            let tmp: ZoneCount = list[i];
            list[i] = list[maxIdx];
            list[maxIdx] = tmp;
        }
    }
    fx {
        loop zc in list {
            println(zc.name, ": ", zc.count);
        }
    }
    ret;
}

