fn main() -> Void {
    let prices: Real[] = [3.50, 2.75, 4.20, 1.99, 6.00];
    let n: Int = length(prices);
    let bestTotal: Real = 0.0;
    let bestCount: Int = 0;
    let bestMask: Int = 0;
    let found: Bool = false;

    loop mask in 0..(1 << n) {
        let total: Real = 0.0;
        let count: Int = 0;
        loop i in 0..n {
            if (mask & (1 << i)) != 0 {
                total = total + prices[i];
                count = count + 1;
            }
        }
        if total <= 12.0 {
            if !found {
                found = true;
                bestTotal = total;
                bestCount = count;
                bestMask = mask;
            } else {
                if total > bestTotal {
                    bestTotal = total;
                    bestCount = count;
                    bestMask = mask;
                } else if total == bestTotal {
                    if count < bestCount {
                        bestCount = count;
                        bestMask = mask;
                    } else if count == bestCount {
                        if mask < bestMask {
                            bestMask = mask;
                        }
                    }
                }
            }
        }
    }

    fx {
        println("BestTotal: ", format_float(bestTotal, 2));
        println("ItemCount: ", bestCount);
    }
    ret;
}

fn main() -> Void {
    let grid: Text[][] = [];
    let r1: Text[] = ["W","W","W","W","W","W","W","W"];
    let r2: Text[] = ["P","P","P","P","P","P","P","P"];
    let r3: Text[] = ["E","E","E","E","E","E","E","E"];
    let r4: Text[] = ["E","E","E","E","E","E","E","E"];
    let r5: Text[] = ["E","E","E","E","E","E","E","E"];
    let r6: Text[] = ["E","E","E","E","E","E","E","E"];
    let r7: Text[] = ["p","p","p","p","p","p","p","p"];
    let r8: Text[] = ["B","B","B","B","B","B","B","B"];
    grid = grid + [r1, r2, r3, r4, r5, r6, r7, r8];

    let board: Int[][] = [];
    loop r in 0..8 {
        let row: Int[] = [];
        loop c in 0..8 {
            let ch: Text = grid[r][c];
            let v: Int = 0;
            if ch == "W" {
                v = 1;
            }
            if ch == "B" {
                v = 2;
            }
            if ch == "P" {
                if c <= 3 {
                    v = 1;
                } else {
                    v = 2;
                }
            }
            if ch == "p" {
                if c <= 3 {
                    v = 2;
                } else {
                    v = 1;
                }
            }
            row = row + [v];
        }
        board = board + [row];
    }

    let whiteCount: Int = 0;
    let blackCount: Int = 0;
    let emptyCount: Int = 0;
    loop r in 0..8 {
        loop c in 0..8 {
            if board[r][c] == 1 {
                whiteCount = whiteCount + 1;
            }
            if board[r][c] == 2 {
                blackCount = blackCount + 1;
            }
            if board[r][c] == 0 {
                emptyCount = emptyCount + 1;
            }
        }
    }

    let visited: Bool[][] = [];
    loop r in 0..8 {
        let row: Bool[] = [false; 8];
        visited = visited + [row];
    }

    let whiteClusters: Int = 0;
    let blackClusters: Int = 0;
    let largest: Int = 0;

    loop r in 0..8 {
        loop c in 0..8 {
            if !visited[r][c] && board[r][c] != 0 {
                let colour: Int = board[r][c];
                let size: Int = 0;
                let stackR: Int[] = [r];
                let stackC: Int[] = [c];
                visited[r][c] = true;
                loop {
                    if length(stackR) == 0 {
                        break;
                    }
                    let top: Int = length(stackR) - 1;
                    let cr: Int = stackR[top];
                    let cc: Int = stackC[top];
                    stackR = stackR[..top];
                    stackC = stackC[..top];
                    size = size + 1;
                    if cr > 0 && !visited[cr-1][cc] && board[cr-1][cc] == colour {
                        visited[cr-1][cc] = true;
                        stackR = stackR + [cr-1];
                        stackC = stackC + [cc];
                    }
                    if cr < 7 && !visited[cr+1][cc] && board[cr+1][cc] == colour {
                        visited[cr+1][cc] = true;
                        stackR = stackR + [cr+1];
                        stackC = stackC + [cc];
                    }
                    if cc > 0 && !visited[cr][cc-1] && board[cr][cc-1] == colour {
                        visited[cr][cc-1] = true;
                        stackR = stackR + [cr];
                        stackC = stackC + [cc-1];
                    }
                    if cc < 7 && !visited[cr][cc+1] && board[cr][cc+1] == colour {
                        visited[cr][cc+1] = true;
                        stackR = stackR + [cr];
                        stackC = stackC + [cc+1];
                    }
                }
                if colour == 1 {
                    whiteClusters = whiteClusters + 1;
                }
                if colour == 2 {
                    blackClusters = blackClusters + 1;
                }
                if size > largest {
                    largest = size;
                }
            }
        }
    }

    fx {
        println("White squares: ", whiteCount);
        println("Black squares: ", blackCount);
        println("Empty squares: ", emptyCount);
        println("White clusters: ", whiteClusters);
        println("Black clusters: ", blackClusters);
        println("Largest cluster size: ", largest);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [2, 2, 2, 2, 2, 2],
        [2, 0, 0, 0, 0, 2],
        [2, 0, 1, 1, 0, 2],
        [2, 0, 1, 1, 0, 2],
        [2, 0, 0, 0, 0, 2],
        [2, 2, 2, 2, 2, 2]
    ];

    let fencePosts: Int = 0;
    let flowerBeds: Int = 0;
    let openSoil: Int = 0;
    let interiorCells: Int = 0;

    loop r in 0..6 {
        loop c in 0..6 {
            let v: Int = grid[r][c];
            if v == 2 {
                fencePosts = fencePosts + 1;
            } else if v == 1 {
                flowerBeds = flowerBeds + 1;
            } else {
                openSoil = openSoil + 1;
            }
            if r > 0 && r < 5 && c > 0 && c < 5 {
                interiorCells = interiorCells + 1;
            }
        }
    }

    let enclosed: Int = 0;
    loop r in 1..5 {
        loop c in 1..5 {
            let v: Int = grid[r][c];
            if v != 2 {
                enclosed = enclosed + 1;
            }
        }
    }

    fx {
        println("Fence posts: ", fencePosts);
        println("Flower beds: ", flowerBeds);
        println("Open soil: ", openSoil);
        println("Enclosed interior cells: ", enclosed);
        println("Interior cells: ", interiorCells);
    }
    ret;
}
